//   새 문장을 추가할 때 topic에 기능명을 새로 넣지 말고, 소재가 있으면 소재명을, 없으면 function과 같은 값을 넣어요.
window.SENTENCES = window.SENTENCES || {};
window.SENTENCES.part5 = [
  { id: "p5-001", topic: "의견 시작", function: "의견 시작", en: "In my opinion, working from home is more efficient than working in an office.", ko: "내 생각에는 재택근무가 사무실 근무보다 더 효율적이다.", pron: "인 마이 오피니언 워킹 프럼 홈 이즈 모어 이피션트 댄 워킹 이너 노피스", keys: [ { en: "In my opinion", ko: "내 생각에는" }, { en: "working from home", ko: "재택근무" }, { en: "more efficient than", ko: "~보다 더 효율적인" } ] },
  { id: "p5-002", topic: "의견 시작", function: "의견 시작", en: "I strongly believe that companies should offer flexible working hours to their employees.", ko: "나는 회사가 직원들에게 유연 근무 시간을 제공해야 한다고 강력히 믿는다.", pron: "아이 스트롱리 빌리브 댓 컴퍼니즈 슈드 오퍼 플렉서블 워킹 아워즈 투 데어 엠플로이이즈", keys: [ { en: "I strongly believe that", ko: "나는 ~라고 강력히 믿는다" }, { en: "offer", ko: "제공하다" }, { en: "flexible working hours", ko: "유연 근무 시간" } ] },
  { id: "p5-003", topic: "의견 시작", function: "의견 시작", en: "Personally, I prefer working in a team rather than working alone.", ko: "개인적으로 나는 혼자 일하는 것보다 팀으로 일하는 것을 선호한다.", pron: "퍼스널리 아이 프리퍼 워킹 이너 팀 래더 댄 워킹 얼론", keys: [ { en: "Personally", ko: "개인적으로" }, { en: "prefer A rather than B", ko: "B보다 A를 선호하다" }, { en: "working alone", ko: "혼자 일하기" } ] },
  { id: "p5-004", topic: "의견 시작", function: "의견 시작", en: "I completely agree with the idea that technology has made our lives easier.", ko: "나는 기술이 우리의 삶을 더 편하게 만들었다는 생각에 전적으로 동의한다.", pron: "아이 컴플리틀리 어그리 위디 아이디어 댓 테크날러지 해즈 메이드 아워 라이브즈 이지어", keys: [ { en: "completely agree with", ko: "~에 전적으로 동의하다" }, { en: "the idea that", ko: "~라는 생각" }, { en: "made our lives easier", ko: "우리 삶을 더 편하게 만들었다" } ] },
  { id: "p5-005", topic: "의견 시작", function: "의견 시작", en: "I disagree with the statement that online classes are as effective as traditional classes.", ko: "나는 온라인 수업이 전통적인 수업만큼 효과적이라는 주장에 동의하지 않는다.", pron: "아이 디서그리 위더 스테잇먼트 댓 온라인 클래시즈 아래즈 이펙티브 애즈 트래디셔널 클래시즈", keys: [ { en: "disagree with the statement", ko: "그 주장에 동의하지 않다" }, { en: "as effective as", ko: "~만큼 효과적인" } ] },
  { id: "p5-006", topic: "의견 시작", function: "의견 시작", en: "From my point of view, a good leader should listen carefully to team members.", ko: "내 관점에서 좋은 리더는 팀원들의 말을 주의 깊게 들어야 한다.", pron: "프럼 마이 포인터브 뷰 어 굿 리더 슈드 리슨 케어풀리 투 팀 멤버즈", keys: [ { en: "From my point of view", ko: "내 관점에서" }, { en: "listen carefully to", ko: "~의 말을 주의 깊게 듣다" } ] },
  { id: "p5-007", topic: "의견 시작", function: "의견 시작", en: "As far as I'm concerned, the most important skill for a manager is communication.", ko: "내가 보기에 관리자에게 가장 중요한 기술은 의사소통이다.", pron: "애즈 파 애즈 아임 컨선드 더 모스트 임포턴트 스킬 포러 매니저 이즈 커뮤니케이션", keys: [ { en: "As far as I'm concerned", ko: "내가 보기에는" }, { en: "the most important skill", ko: "가장 중요한 기술" } ] },
  { id: "p5-008", topic: "의견 시작", function: "의견 시작", en: "I think it's better for young people to gain work experience before going to college.", ko: "나는 젊은이들이 대학에 가기 전에 업무 경험을 쌓는 것이 더 낫다고 생각한다.", pron: "아이 띵크 잇츠 베러 포 영 피플 투 게인 웍 익스피리언스 비포어 고잉 투 칼리지", keys: [ { en: "it's better for A to", ko: "A가 ~하는 것이 더 낫다" }, { en: "gain work experience", ko: "업무 경험을 쌓다" } ] },
  { id: "p5-009", topic: "의견 시작", function: "의견 시작", en: "There are several reasons why I believe social media has a negative effect on teenagers.", ko: "소셜 미디어가 십 대들에게 부정적인 영향을 미친다고 생각하는 데에는 몇 가지 이유가 있다.", pron: "데어라 세버럴 리즌즈 와이 아이 빌리브 소셜 미디아 해즈 어 네거티브 이펙트 온 틴에이저즈", keys: [ { en: "There are several reasons why", ko: "~하는 데에는 몇 가지 이유가 있다" }, { en: "have a negative effect on", ko: "~에 부정적인 영향을 미치다" } ] },
  { id: "p5-010", topic: "의견 시작", function: "의견 시작", en: "I'd rather live in a big city than in a small town for several reasons.", ko: "나는 몇 가지 이유로 작은 마을보다 대도시에 사는 것이 더 좋다.", pron: "아이드 래더 리빈 어 빅 시티 댄 이너 스몰 타운 포 세버럴 리즌즈", keys: [ { en: "I'd rather A than B", ko: "B보다 차라리 A하겠다" }, { en: "for several reasons", ko: "몇 가지 이유로" } ] },
  { id: "p5-011", topic: "의견 시작", function: "의견 시작", en: "If I had to choose, I would definitely choose a job with a good work-life balance.", ko: "내가 골라야 한다면, 나는 분명히 일과 삶의 균형이 좋은 직업을 고를 것이다.", pron: "이프 아이 해투 츄즈 아이 우드 데피니틀리 츄저 잡 위더 굿 웍 라이프 밸런스", keys: [ { en: "If I had to choose", ko: "내가 골라야 한다면" }, { en: "definitely", ko: "분명히" }, { en: "work-life balance", ko: "일과 삶의 균형" } ] },
  { id: "p5-012", topic: "의견 시작", function: "의견 시작", en: "To be honest, I don't think a high salary is the most important factor in a job.", ko: "솔직히 말해서, 나는 높은 연봉이 직업에서 가장 중요한 요소라고 생각하지 않는다.", pron: "투 비 아너스트 아이 돈 띵커 하이 샐러리 이즈 더 모스트 임포턴트 팩터 이너 잡", keys: [ { en: "To be honest", ko: "솔직히 말해서" }, { en: "high salary", ko: "높은 연봉" }, { en: "the most important factor", ko: "가장 중요한 요소" } ] },
  { id: "p5-013", topic: "의견 시작", function: "의견 시작", en: "I'm in favor of companies providing free training programs for their employees.", ko: "나는 회사가 직원들에게 무료 교육 프로그램을 제공하는 것에 찬성한다.", pron: "아임 인 페이버로브 컴퍼니즈 프러바이딩 프리 트레이닝 프로그램즈 포 데어 엠플로이이즈", keys: [ { en: "be in favor of", ko: "~에 찬성하다" }, { en: "training programs", ko: "교육 프로그램" } ] },
  { id: "p5-014", topic: "의견 시작", function: "의견 시작", en: "I'm against the idea of banning smartphones in the workplace completely.", ko: "나는 직장에서 스마트폰을 완전히 금지하는 생각에 반대한다.", pron: "아임 어겐스트 디 아이디어로브 배닝 스마트폰즈 인 더 웍플레이스 컴플리틀리", keys: [ { en: "be against the idea of", ko: "~하는 생각에 반대하다" }, { en: "ban", ko: "금지하다" }, { en: "workplace", ko: "직장" } ] },
  { id: "p5-015", topic: "의견 시작", function: "의견 시작", en: "It seems to me that teamwork is more important than individual talent in most companies.", ko: "내가 보기에 대부분의 회사에서는 개인의 재능보다 팀워크가 더 중요한 것 같다.", pron: "잇 씸즈 투 미 댓 팀웍 이즈 모어 임포턴트 댄 인디비주얼 탤런트 인 모스트 컴퍼니즈", keys: [ { en: "It seems to me that", ko: "내가 보기에 ~인 것 같다" }, { en: "individual talent", ko: "개인의 재능" } ] },
  { id: "p5-016", topic: "의견 시작", function: "의견 시작", en: "I believe that the advantages of remote work outweigh the disadvantages.", ko: "나는 원격 근무의 장점이 단점보다 더 크다고 믿는다.", pron: "아이 빌리브 댓 디 어드밴티지즈 오브 리모트 웍 아웃웨이 더 디스어드밴티지즈", keys: [ { en: "advantages", ko: "장점" }, { en: "outweigh", ko: "~보다 더 크다, 능가하다" }, { en: "disadvantages", ko: "단점" } ] },
  { id: "p5-017", topic: "의견 시작", function: "의견 시작", en: "Generally speaking, I think older employees can be great mentors for younger workers.", ko: "일반적으로 말해서, 나는 나이 든 직원들이 젊은 직원들에게 훌륭한 멘토가 될 수 있다고 생각한다.", pron: "제너럴리 스피킹 아이 띵크 올더 엠플로이이즈 캔 비 그레잇 멘토어즈 포 영거 워커즈", keys: [ { en: "Generally speaking", ko: "일반적으로 말해서" }, { en: "great mentors", ko: "훌륭한 멘토" } ] },
  { id: "p5-018", topic: "의견 시작", function: "의견 시작", en: "I'm convinced that learning a foreign language is essential for career success.", ko: "나는 외국어를 배우는 것이 직업적 성공에 필수적이라고 확신한다.", pron: "아임 컨빈스트 댓 러닝 어 포린 랭귀지 이즈 이센셜 포 커리어 석세스", keys: [ { en: "I'm convinced that", ko: "나는 ~라고 확신한다" }, { en: "essential for", ko: "~에 필수적인" }, { en: "career success", ko: "직업적 성공" } ] },
  { id: "p5-019", topic: "의견 시작", function: "의견 시작", en: "Both options have merits, but I would prefer to work for a large company.", ko: "두 선택지 모두 장점이 있지만, 나는 대기업에서 일하는 것을 선호한다.", pron: "보쓰 압션즈 해브 메릿츠 벗 아이 우드 프리퍼 투 웍 포러 라지 컴퍼니", keys: [ { en: "have merits", ko: "장점이 있다" }, { en: "would prefer to", ko: "~하는 것을 선호하다" } ] },
  { id: "p5-020", topic: "의견 시작", function: "의견 시작", en: "In my view, governments should invest more money in public transportation.", ko: "내 견해로는 정부가 대중교통에 더 많은 돈을 투자해야 한다.", pron: "인 마이 뷰 거번먼츠 슈드 인베스트 모어 머니 인 퍼블릭 트랜스포테이션", keys: [ { en: "In my view", ko: "내 견해로는" }, { en: "invest in", ko: "~에 투자하다" }, { en: "public transportation", ko: "대중교통" } ] },
  { id: "p5-021", topic: "이유", function: "이유", en: "The main reason is that I can save a lot of time by not commuting.", ko: "주된 이유는 출퇴근을 하지 않음으로써 많은 시간을 절약할 수 있다는 것이다.", pron: "더 메인 리즌 이즈 댓 아이 캔 세이브 얼라러브 타임 바이 낫 커뮤팅", keys: [ { en: "The main reason is that", ko: "주된 이유는 ~이다" }, { en: "save a lot of time", ko: "많은 시간을 절약하다" }, { en: "commuting", ko: "출퇴근" } ] },
  { id: "p5-022", topic: "이유", function: "이유", en: "First of all, working in a team allows people to share different ideas.", ko: "우선, 팀으로 일하면 사람들이 다양한 아이디어를 공유할 수 있다.", pron: "퍼스트 오브 올 워킹 이너 팀 얼라우즈 피플 투 쉐어 디퍼런트 아이디어즈", keys: [ { en: "First of all", ko: "우선, 무엇보다도" }, { en: "allow A to", ko: "A가 ~하게 해 주다" }, { en: "share different ideas", ko: "다양한 아이디어를 공유하다" } ] },
  { id: "p5-023", topic: "이유", function: "이유", en: "Another reason is that online learning lets students study at their own pace.", ko: "또 다른 이유는 온라인 학습이 학생들에게 자신의 속도로 공부할 수 있게 해 준다는 것이다.", pron: "어나더 리즌 이즈 댓 온라인 러닝 렛츠 스튜던츠 스터디 앳 데어 오운 페이스", keys: [ { en: "Another reason is that", ko: "또 다른 이유는 ~이다" }, { en: "at their own pace", ko: "자신의 속도로" } ] },
  { id: "p5-024", topic: "이유", function: "이유", en: "This is because employees feel more motivated when their efforts are recognized.", ko: "이는 직원들이 자신의 노력을 인정받을 때 더 동기 부여를 느끼기 때문이다.", pron: "디스 이즈 비코즈 엠플로이이즈 필 모어 모티베이티드 웬 데어 에포츠 아 레커그나이즈드", keys: [ { en: "This is because", ko: "이는 ~ 때문이다" }, { en: "feel motivated", ko: "동기 부여를 느끼다" }, { en: "be recognized", ko: "인정받다" } ] },
  { id: "p5-025", topic: "이유", function: "이유", en: "Most importantly, a clear goal helps the whole team stay focused.", ko: "가장 중요한 것은, 명확한 목표가 팀 전체가 집중력을 유지하도록 돕는다는 것이다.", pron: "모스트 임포턴틀리 어 클리어 고울 헬프스 더 호울 팀 스테이 포커스트", keys: [ { en: "Most importantly", ko: "가장 중요한 것은" }, { en: "a clear goal", ko: "명확한 목표" }, { en: "stay focused", ko: "집중력을 유지하다" } ] },
  { id: "p5-026", topic: "이유", function: "이유", en: "One of the biggest advantages is that technology makes communication faster and cheaper.", ko: "가장 큰 장점 중 하나는 기술이 의사소통을 더 빠르고 저렴하게 만든다는 것이다.", pron: "워너브 더 비기스트 어드밴티지즈 이즈 댓 테크날러지 메익스 커뮤니케이션 패스터 앤 치퍼", keys: [ { en: "One of the biggest advantages", ko: "가장 큰 장점 중 하나" }, { en: "faster and cheaper", ko: "더 빠르고 저렴한" } ] },
  { id: "p5-027", topic: "이유", function: "이유", en: "Secondly, living in a city gives you easy access to hospitals, shops, and cultural events.", ko: "둘째로, 도시에 살면 병원, 상점, 문화 행사를 쉽게 이용할 수 있다.", pron: "세컨들리 리빙 이너 시티 기브쥬 이지 액세스 투 하스피털즈 샵스 앤 컬처럴 이벤츠", keys: [ { en: "Secondly", ko: "둘째로" }, { en: "easy access to", ko: "~에 대한 쉬운 접근" }, { en: "cultural events", ko: "문화 행사" } ] },
  { id: "p5-028", topic: "이유", function: "이유", en: "Without face-to-face interaction, it's difficult to build trust among coworkers.", ko: "대면 교류가 없으면 동료들 사이에 신뢰를 쌓기 어렵다.", pron: "위다웃 페이스 투 페이스 인터랙션 잇츠 디피컬트 투 빌드 트러스트 어멍 코워커즈", keys: [ { en: "face-to-face interaction", ko: "대면 교류" }, { en: "build trust", ko: "신뢰를 쌓다" }, { en: "coworkers", ko: "동료들" } ] },
  { id: "p5-029", topic: "이유", function: "이유", en: "On top of that, flexible schedules can reduce stress and improve productivity.", ko: "게다가 유연한 일정은 스트레스를 줄이고 생산성을 높일 수 있다.", pron: "온 타퍼브 댓 플렉서블 스케줄즈 캔 리듀스 스트레스 앤 임프루브 프러덕티비티", keys: [ { en: "On top of that", ko: "게다가" }, { en: "reduce stress", ko: "스트레스를 줄이다" }, { en: "improve productivity", ko: "생산성을 높이다" } ] },
  { id: "p5-030", topic: "이유", function: "이유", en: "In addition, small companies usually give employees more chances to take on responsibility.", ko: "또한 작은 회사들은 보통 직원들에게 책임을 맡을 기회를 더 많이 준다.", pron: "이너디션 스몰 컴퍼니즈 유주얼리 기브 엠플로이이즈 모어 챈시즈 투 테이컨 리스판서빌러티", keys: [ { en: "In addition", ko: "또한, 게다가" }, { en: "more chances to", ko: "~할 더 많은 기회" }, { en: "take on responsibility", ko: "책임을 맡다" } ] },
  { id: "p5-031", topic: "이유", function: "이유", en: "Customers are more likely to return when they receive friendly and quick service.", ko: "고객들은 친절하고 빠른 서비스를 받을 때 다시 찾아올 가능성이 더 높다.", pron: "커스터머즈 아 모어 라이클리 투 리턴 웬 데이 리시브 프렌들리 앤 퀵 서비스", keys: [ { en: "be more likely to", ko: "~할 가능성이 더 높다" }, { en: "friendly and quick service", ko: "친절하고 빠른 서비스" } ] },
  { id: "p5-032", topic: "이유", function: "이유", en: "Social media can spread false information very quickly, which can cause serious problems.", ko: "소셜 미디어는 잘못된 정보를 매우 빠르게 퍼뜨릴 수 있으며, 이는 심각한 문제를 일으킬 수 있다.", pron: "소셜 미디아 캔 스프레드 폴스 인포메이션 베리 퀵클리 위치 캔 코즈 시리어스 프라블럼즈", keys: [ { en: "spread false information", ko: "잘못된 정보를 퍼뜨리다" }, { en: "cause serious problems", ko: "심각한 문제를 일으키다" } ] },
  { id: "p5-033", topic: "이유", function: "이유", en: "Learning new skills helps workers adapt to rapid changes in the job market.", ko: "새로운 기술을 배우는 것은 근로자들이 취업 시장의 빠른 변화에 적응하도록 돕는다.", pron: "러닝 뉴 스킬즈 헬프스 워커즈 어댑투 래피드 체인지즈 인 더 잡 마킷", keys: [ { en: "adapt to", ko: "~에 적응하다" }, { en: "rapid changes", ko: "빠른 변화" }, { en: "job market", ko: "취업 시장" } ] },
  { id: "p5-034", topic: "이유", function: "이유", en: "If a company protects the environment, it can improve its public image.", ko: "회사가 환경을 보호하면 대중적 이미지를 개선할 수 있다.", pron: "이퍼 컴퍼니 프러텍츠 디 인바이런먼트 잇 캔 임프루브 잇츠 퍼블릭 이미지", keys: [ { en: "protect the environment", ko: "환경을 보호하다" }, { en: "public image", ko: "대중적 이미지" } ] },
  { id: "p5-035", topic: "이유", function: "이유", en: "A good manager can solve conflicts before they become bigger problems.", ko: "좋은 관리자는 갈등이 더 큰 문제가 되기 전에 해결할 수 있다.", pron: "어 굿 매니저 캔 솔브 칸플릭츠 비포어 데이 비컴 비거 프라블럼즈", keys: [ { en: "solve conflicts", ko: "갈등을 해결하다" }, { en: "bigger problems", ko: "더 큰 문제" } ] },
  { id: "p5-036", topic: "이유", function: "이유", en: "It's much easier to concentrate when there are fewer distractions around you.", ko: "주변에 방해 요소가 적을 때 집중하기가 훨씬 쉽다.", pron: "잇츠 머치 이지어 투 칸센트레잇 웬 데어라 퓨어 디스트랙션즈 어라운쥬", keys: [ { en: "much easier to", ko: "~하기 훨씬 쉬운" }, { en: "concentrate", ko: "집중하다" }, { en: "fewer distractions", ko: "더 적은 방해 요소" } ] },
  { id: "p5-037", topic: "이유", function: "이유", en: "Experienced workers have practical knowledge that cannot be learned from textbooks.", ko: "경험 많은 근로자들은 교과서로는 배울 수 없는 실용적인 지식을 가지고 있다.", pron: "익스피리언스트 워커즈 해브 프랙티컬 날리지 댓 캐낫 비 런드 프럼 텍스트북스", keys: [ { en: "experienced workers", ko: "경험 많은 근로자" }, { en: "practical knowledge", ko: "실용적인 지식" } ] },
  { id: "p5-038", topic: "이유", function: "이유", en: "Regular meetings help everyone understand the project's progress and their own roles.", ko: "정기 회의는 모두가 프로젝트의 진행 상황과 자신의 역할을 이해하도록 돕는다.", pron: "레귤러 미팅즈 헬프 에브리원 언더스탠 더 프라젝츠 프라그레스 앤 데어 오운 롤즈", keys: [ { en: "regular meetings", ko: "정기 회의" }, { en: "progress", ko: "진행 상황" }, { en: "their own roles", ko: "자신의 역할" } ] },
  { id: "p5-039", topic: "이유", function: "이유", en: "Public transportation reduces traffic jams and air pollution in crowded cities.", ko: "대중교통은 붐비는 도시의 교통 체증과 대기 오염을 줄여 준다.", pron: "퍼블릭 트랜스포테이션 리듀시즈 트래픽 잼즈 앤 에어 펄루션 인 크라우디드 시티즈", keys: [ { en: "traffic jams", ko: "교통 체증" }, { en: "air pollution", ko: "대기 오염" }, { en: "crowded cities", ko: "붐비는 도시" } ] },
  { id: "p5-040", topic: "이유", function: "이유", en: "Online courses are usually much cheaper than classes at a traditional school.", ko: "온라인 강좌는 보통 전통적인 학교의 수업보다 훨씬 저렴하다.", pron: "온라인 코어시즈 아 유주얼리 머치 치퍼 댄 클래시즈 애러 트래디셔널 스쿨", keys: [ { en: "online courses", ko: "온라인 강좌" }, { en: "much cheaper than", ko: "~보다 훨씬 저렴한" } ] },
  { id: "p5-041", topic: "예시", function: "예시", en: "For example, when I worked at a marketing company, I could finish my reports faster at home.", ko: "예를 들어, 내가 마케팅 회사에서 일했을 때 나는 집에서 보고서를 더 빨리 끝낼 수 있었다.", pron: "포 이그잼플 웬 아이 웍탯 어 마케팅 컴퍼니 아이 쿳 피니쉬 마이 리포츠 패스터 앳 홈", keys: [ { en: "For example", ko: "예를 들어" }, { en: "when I worked at", ko: "내가 ~에서 일했을 때" }, { en: "finish my reports", ko: "보고서를 끝내다" } ] },
  { id: "p5-042", topic: "예시", function: "예시", en: "For instance, my team once solved a difficult problem by sharing ideas in a meeting.", ko: "예를 들어, 우리 팀은 한번 회의에서 아이디어를 공유해서 어려운 문제를 해결했다.", pron: "포 인스턴스 마이 팀 원스 솔브더 디피컬트 프라블럼 바이 쉐어링 아이디어즈 이너 미팅", keys: [ { en: "For instance", ko: "예를 들어" }, { en: "solve a difficult problem", ko: "어려운 문제를 해결하다" }, { en: "by sharing ideas", ko: "아이디어를 공유함으로써" } ] },
  { id: "p5-043", topic: "예시", function: "예시", en: "Let me give you an example from my own experience.", ko: "내 경험에서 나온 예를 하나 들어 보겠다.", pron: "렛 미 기뷰 언 이그잼플 프럼 마이 오운 익스피리언스", keys: [ { en: "Let me give you an example", ko: "예를 하나 들어 보겠다" }, { en: "from my own experience", ko: "내 경험에서" } ] },
  { id: "p5-044", topic: "예시", function: "예시", en: "When I was in college, I took an online course and learned a lot at my own pace.", ko: "대학에 다닐 때 나는 온라인 강좌를 들었고 내 속도에 맞춰 많은 것을 배웠다.", pron: "웬 아이 워즈 인 칼리지 아이 투컨 온라인 코어스 앤 런더 랏 앳 마이 오운 페이스", keys: [ { en: "took an online course", ko: "온라인 강좌를 들었다" }, { en: "learned a lot", ko: "많이 배웠다" }, { en: "at my own pace", ko: "내 속도로" } ] },
  { id: "p5-045", topic: "예시", function: "예시", en: "A friend of mine started working from home last year, and she says she is much happier now.", ko: "내 친구 한 명이 작년에 재택근무를 시작했는데, 지금 훨씬 더 행복하다고 말한다.", pron: "어 프렌더브 마인 스타티드 워킹 프럼 홈 래스트 이어 앤 쉬 세즈 쉬즈 머치 해피어 나우", keys: [ { en: "A friend of mine", ko: "내 친구 한 명" }, { en: "started working from home", ko: "재택근무를 시작했다" }, { en: "much happier", ko: "훨씬 더 행복한" } ] },
  { id: "p5-046", topic: "예시", function: "예시", en: "In my previous job, my manager always asked for our opinions before making decisions.", ko: "이전 직장에서 내 상사는 결정을 내리기 전에 항상 우리의 의견을 물었다.", pron: "인 마이 프리비어스 잡 마이 매니저 올웨이즈 애슥트 포 아워 오피니언즈 비포어 메이킹 디시전즈", keys: [ { en: "previous job", ko: "이전 직장" }, { en: "ask for opinions", ko: "의견을 묻다" }, { en: "make decisions", ko: "결정을 내리다" } ] },
  { id: "p5-047", topic: "예시", function: "예시", en: "Take my company, for example; it introduced flexible hours, and productivity went up by twenty percent.", ko: "우리 회사를 예로 들면, 유연 근무제를 도입했고 생산성이 20퍼센트 올랐다.", pron: "테익 마이 컴퍼니 포 이그잼플 잇 인트러듀스트 플렉서블 아워즈 앤 프러덕티비티 웬텁 바이 트웨니 퍼센트", keys: [ { en: "Take A, for example", ko: "A를 예로 들어 보자" }, { en: "introduced flexible hours", ko: "유연 근무제를 도입했다" }, { en: "went up by", ko: "~만큼 올랐다" } ] },
  { id: "p5-048", topic: "예시", function: "예시", en: "When I used a video conferencing app, I could talk with clients in other countries easily.", ko: "화상 회의 앱을 사용했을 때 나는 다른 나라의 고객들과 쉽게 이야기할 수 있었다.", pron: "웬 아이 유즈더 비디오 칸퍼런싱 앱 아이 쿳 토크 위드 클라이언츠 인 아더 컨트리즈 이즐리", keys: [ { en: "video conferencing app", ko: "화상 회의 앱" }, { en: "talk with clients", ko: "고객과 이야기하다" } ] },
  { id: "p5-049", topic: "예시", function: "예시", en: "I remember a time when our team missed a deadline because of poor communication.", ko: "우리 팀이 의사소통 부족 때문에 마감 기한을 놓쳤던 때가 기억난다.", pron: "아이 리멤버 어 타임 웬 아워 팀 미스터 데드라인 비코저브 푸어 커뮤니케이션", keys: [ { en: "I remember a time when", ko: "~했던 때가 기억난다" }, { en: "missed a deadline", ko: "마감 기한을 놓쳤다" }, { en: "poor communication", ko: "의사소통 부족" } ] },
  { id: "p5-050", topic: "예시", function: "예시", en: "My younger brother spends too much time on social media, and his grades have dropped.", ko: "내 남동생은 소셜 미디어에 너무 많은 시간을 쓰고, 그 결과 성적이 떨어졌다.", pron: "마이 영거 브라더 스펜즈 투 머치 타임 온 소셜 미디아 앤 히즈 그레이즈 해브 드랍트", keys: [ { en: "spend too much time on", ko: "~에 너무 많은 시간을 쓰다" }, { en: "grades have dropped", ko: "성적이 떨어졌다" } ] },
  { id: "p5-051", topic: "예시", function: "예시", en: "Last month, I attended a training workshop that really helped me improve my presentation skills.", ko: "지난달 나는 발표 능력을 향상하는 데 정말 도움이 된 교육 워크숍에 참석했다.", pron: "래스트 먼쓰 아이 어텐디더 트레이닝 웍샵 댓 리얼리 헬프트 미 임프루브 마이 프레젠테이션 스킬즈", keys: [ { en: "attended a training workshop", ko: "교육 워크숍에 참석했다" }, { en: "helped me improve", ko: "내가 향상하도록 도왔다" }, { en: "presentation skills", ko: "발표 능력" } ] },
  { id: "p5-052", topic: "예시", function: "예시", en: "When I lived in Seoul, I could get almost anywhere by subway in less than an hour.", ko: "서울에 살았을 때 나는 지하철로 거의 어디든 한 시간 이내에 갈 수 있었다.", pron: "웬 아이 리브딘 서울 아이 쿳 겟 올모스트 애니웨어 바이 섭웨이 인 레스 대넌 아워", keys: [ { en: "get almost anywhere", ko: "거의 어디든 가다" }, { en: "by subway", ko: "지하철로" }, { en: "in less than an hour", ko: "한 시간 이내에" } ] },
  { id: "p5-053", topic: "예시", function: "예시", en: "Once, a store clerk helped me find the right product, so I became a regular customer.", ko: "한번은 매장 직원이 내게 맞는 제품을 찾도록 도와줘서 나는 단골손님이 되었다.", pron: "원스 어 스토어 클럭 헬프트 미 파인더 라잇 프라덕트 쏘 아이 비케이머 레귤러 커스터머", keys: [ { en: "helped me find", ko: "내가 찾도록 도와주었다" }, { en: "the right product", ko: "알맞은 제품" }, { en: "regular customer", ko: "단골손님" } ] },
  { id: "p5-054", topic: "예시", function: "예시", en: "According to a recent survey, most employees want more opportunities for training.", ko: "최근 설문 조사에 따르면 대부분의 직원들은 더 많은 교육 기회를 원한다.", pron: "어코딩 투 어 리슨트 서베이 모스트 엠플로이이즈 원트 모어 아퍼튜니티즈 포 트레이닝", keys: [ { en: "According to", ko: "~에 따르면" }, { en: "a recent survey", ko: "최근 설문 조사" }, { en: "opportunities for training", ko: "교육 기회" } ] },
  { id: "p5-055", topic: "예시", function: "예시", en: "My first boss taught me how important it is to take responsibility for my mistakes.", ko: "내 첫 상사는 내 실수에 책임을 지는 것이 얼마나 중요한지 가르쳐 주었다.", pron: "마이 퍼스트 보스 톳 미 하우 임포턴트 잇 이즈 투 테익 리스판서빌러티 포 마이 미스테익스", keys: [ { en: "how important it is to", ko: "~하는 것이 얼마나 중요한지" }, { en: "take responsibility for", ko: "~에 책임을 지다" } ] },
  { id: "p5-056", topic: "예시", function: "예시", en: "My company started a recycling program, and now we produce much less waste.", ko: "우리 회사는 재활용 프로그램을 시작했고, 이제 쓰레기를 훨씬 적게 만든다.", pron: "마이 컴퍼니 스타티더 리사이클링 프로그램 앤 나우 위 프러듀스 머치 레스 웨이스트", keys: [ { en: "recycling program", ko: "재활용 프로그램" }, { en: "produce much less waste", ko: "쓰레기를 훨씬 적게 만들다" } ] },
  { id: "p5-057", topic: "예시", function: "예시", en: "When I joined a new team, a senior coworker helped me adjust quickly.", ko: "내가 새 팀에 합류했을 때 한 선배 동료가 내가 빨리 적응하도록 도와주었다.", pron: "웬 아이 조인더 뉴 팀 어 시니어 코워커 헬프트 미 어저스트 퀵클리", keys: [ { en: "joined a new team", ko: "새 팀에 합류했다" }, { en: "senior coworker", ko: "선배 동료" }, { en: "adjust quickly", ko: "빨리 적응하다" } ] },
  { id: "p5-058", topic: "예시", function: "예시", en: "A few years ago, I changed jobs to find a position with better growth opportunities.", ko: "몇 년 전 나는 더 나은 성장 기회가 있는 자리를 찾기 위해 이직했다.", pron: "어 퓨 이어즈 어고 아이 체인지드 잡스 투 파인더 퍼지션 위드 베러 그로쓰 아퍼튜니티즈", keys: [ { en: "changed jobs", ko: "이직했다" }, { en: "position", ko: "자리, 직책" }, { en: "growth opportunities", ko: "성장 기회" } ] },
  { id: "p5-059", topic: "예시", function: "예시", en: "During the pandemic, many companies proved that remote work can be very successful.", ko: "팬데믹 기간 동안 많은 회사들이 원격 근무가 매우 성공적일 수 있음을 증명했다.", pron: "듀어링 더 팬데믹 매니 컴퍼니즈 프루브드 댓 리모트 웍 캔 비 베리 석세스풀", keys: [ { en: "During the pandemic", ko: "팬데믹 기간 동안" }, { en: "proved that", ko: "~임을 증명했다" }, { en: "remote work", ko: "원격 근무" } ] },
  { id: "p5-060", topic: "예시", function: "예시", en: "Thanks to a mobile banking app, I no longer have to visit the bank in person.", ko: "모바일 뱅킹 앱 덕분에 나는 더 이상 은행에 직접 갈 필요가 없다.", pron: "쌩스 투 어 모바일 뱅킹 앱 아이 노 롱거 해브 투 비지더 뱅크 인 퍼슨", keys: [ { en: "Thanks to", ko: "~ 덕분에" }, { en: "no longer have to", ko: "더 이상 ~할 필요가 없다" }, { en: "in person", ko: "직접" } ] },
  { id: "p5-061", topic: "결론", function: "결론", en: "That's why I think working from home is the better choice for most people.", ko: "그래서 나는 대부분의 사람들에게 재택근무가 더 나은 선택이라고 생각한다.", pron: "댓츠 와이 아이 띵크 워킹 프럼 홈 이즈 더 베러 쵸이스 포 모스트 피플", keys: [ { en: "That's why I think", ko: "그래서 나는 ~라고 생각한다" }, { en: "the better choice", ko: "더 나은 선택" } ] },
  { id: "p5-062", topic: "결론", function: "결론", en: "For these reasons, I believe companies should invest more in employee training.", ko: "이러한 이유로 나는 회사가 직원 교육에 더 많이 투자해야 한다고 믿는다.", pron: "포 디즈 리즌즈 아이 빌리브 컴퍼니즈 슈드 인베스트 모어 인 엠플로이 트레이닝", keys: [ { en: "For these reasons", ko: "이러한 이유로" }, { en: "invest more in", ko: "~에 더 많이 투자하다" }, { en: "employee training", ko: "직원 교육" } ] },
  { id: "p5-063", topic: "결론", function: "결론", en: "In conclusion, I strongly believe that teamwork is the key to success.", ko: "결론적으로 나는 팀워크가 성공의 열쇠라고 강력히 믿는다.", pron: "인 컨클루전 아이 스트롱리 빌리브 댓 팀웍 이즈 더 키 투 석세스", keys: [ { en: "In conclusion", ko: "결론적으로" }, { en: "the key to success", ko: "성공의 열쇠" } ] },
  { id: "p5-064", topic: "결론", function: "결론", en: "All things considered, the benefits of technology are much greater than its drawbacks.", ko: "모든 것을 고려해 볼 때, 기술의 이점은 단점보다 훨씬 크다.", pron: "올 띵즈 컨시더드 더 베니핏츠 오브 테크날러지 아 머치 그레이터 댄 잇츠 드로백스", keys: [ { en: "All things considered", ko: "모든 것을 고려해 볼 때" }, { en: "benefits", ko: "이점" }, { en: "drawbacks", ko: "단점, 결점" } ] },
  { id: "p5-065", topic: "결론", function: "결론", en: "To sum up, I prefer living in a city because it offers more opportunities.", ko: "요약하자면, 나는 도시가 더 많은 기회를 제공하기 때문에 도시에 사는 것을 선호한다.", pron: "투 써멉 아이 프리퍼 리빙 이너 시티 비코즈 잇 오퍼즈 모어 아퍼튜니티즈", keys: [ { en: "To sum up", ko: "요약하자면" }, { en: "offers more opportunities", ko: "더 많은 기회를 제공하다" } ] },
  { id: "p5-066", topic: "결론", function: "결론", en: "Therefore, I think online learning is a great option for busy working adults.", ko: "따라서 나는 온라인 학습이 바쁜 직장인들에게 훌륭한 선택이라고 생각한다.", pron: "데어포어 아이 띵크 온라인 러닝 이즈 어 그레잇 압션 포 비지 워킹 어덜츠", keys: [ { en: "Therefore", ko: "따라서" }, { en: "a great option", ko: "훌륭한 선택" }, { en: "working adults", ko: "직장인" } ] },
  { id: "p5-067", topic: "결론", function: "결론", en: "So, overall, I agree that a good leader should set a positive example.", ko: "그래서 전반적으로 나는 좋은 리더가 긍정적인 본보기가 되어야 한다는 데 동의한다.", pron: "쏘 오버롤 아이 어그리 댓 어 굿 리더 슈드 세러 파지티브 이그잼플", keys: [ { en: "overall", ko: "전반적으로" }, { en: "set a positive example", ko: "긍정적인 본보기가 되다" } ] },
  { id: "p5-068", topic: "결론", function: "결론", en: "This is the main reason why I support flexible working hours.", ko: "이것이 내가 유연 근무 시간을 지지하는 주된 이유이다.", pron: "디스 이즈 더 메인 리즌 와이 아이 서포트 플렉서블 워킹 아워즈", keys: [ { en: "the main reason why", ko: "~하는 주된 이유" }, { en: "support", ko: "지지하다" } ] },
  { id: "p5-069", topic: "연결", function: "연결", en: "On the other hand, I understand that some people feel lonely when they work from home.", ko: "반면에 나는 일부 사람들이 재택근무를 할 때 외로움을 느낀다는 것을 이해한다.", pron: "온 디 아더 핸드 아이 언더스탠 댓 썸 피플 필 론리 웬 데이 웍 프럼 홈", keys: [ { en: "On the other hand", ko: "반면에" }, { en: "feel lonely", ko: "외로움을 느끼다" } ] },
  { id: "p5-070", topic: "연결", function: "연결", en: "Of course, there are some disadvantages, but I still think the advantages are more important.", ko: "물론 몇 가지 단점이 있지만, 나는 여전히 장점이 더 중요하다고 생각한다.", pron: "어브 코어스 데어라 썸 디스어드밴티지즈 벗 아이 스틸 띵크 디 어드밴티지즈 아 모어 임포턴트", keys: [ { en: "Of course", ko: "물론" }, { en: "I still think", ko: "나는 여전히 ~라고 생각한다" } ] },
  { id: "p5-071", topic: "연결", function: "연결", en: "However, it's important to use social media wisely and limit the time we spend on it.", ko: "하지만 소셜 미디어를 현명하게 사용하고 그것에 쓰는 시간을 제한하는 것이 중요하다.", pron: "하우에버 잇츠 임포턴트 투 유즈 소셜 미디아 와이즐리 앤 리밋 더 타임 위 스펜던 잇", keys: [ { en: "However", ko: "하지만" }, { en: "use wisely", ko: "현명하게 사용하다" }, { en: "limit the time", ko: "시간을 제한하다" } ] },
  { id: "p5-072", topic: "연결", function: "연결", en: "As a result, our team was able to finish the project ahead of schedule.", ko: "그 결과, 우리 팀은 예정보다 일찍 프로젝트를 끝낼 수 있었다.", pron: "애저 리절트 아워 팀 워즈 에이블 투 피니쉬 더 프라젝트 어헤더브 스케줄", keys: [ { en: "As a result", ko: "그 결과" }, { en: "was able to", ko: "~할 수 있었다" }, { en: "ahead of schedule", ko: "예정보다 일찍" } ] },
  { id: "p5-073", topic: "연결", function: "연결", en: "Because of this experience, I now believe that communication is the most important part of teamwork.", ko: "이 경험 때문에 나는 이제 의사소통이 팀워크의 가장 중요한 부분이라고 믿는다.", pron: "비코저브 디스 익스피리언스 아이 나우 빌리브 댓 커뮤니케이션 이즈 더 모스트 임포턴트 파러브 팀웍", keys: [ { en: "Because of this experience", ko: "이 경험 때문에" }, { en: "the most important part of", ko: "~의 가장 중요한 부분" } ] },
  { id: "p5-074", topic: "연결", function: "연결", en: "Even though city life can be stressful, I think the benefits are worth it.", ko: "도시 생활은 스트레스가 많을 수 있지만, 나는 그만한 가치가 있다고 생각한다.", pron: "이븐 도우 시티 라이프 캔 비 스트레스풀 아이 띵크 더 베니핏츠 아 워쓰 잇", keys: [ { en: "Even though", ko: "비록 ~이지만" }, { en: "stressful", ko: "스트레스가 많은" }, { en: "worth it", ko: "그만한 가치가 있는" } ] },
  { id: "p5-075", topic: "결론", function: "결론", en: "That's why I believe this policy would be good for both employees and the company.", ko: "그래서 나는 이 정책이 직원과 회사 모두에게 좋을 것이라고 믿는다.", pron: "댓츠 와이 아이 빌리브 디스 팔러시 우드 비 굿 포 보쓰 엠플로이이즈 앤 더 컴퍼니", keys: [ { en: "That's why I believe", ko: "그래서 나는 ~라고 믿는다" }, { en: "policy", ko: "정책" }, { en: "both A and B", ko: "A와 B 둘 다" } ] },
  { id: "p5-076", topic: "직장", function: "의견 시작", en: "I think companies should allow employees to choose where they want to work.", ko: "나는 회사가 직원들이 일하고 싶은 장소를 선택할 수 있게 해야 한다고 생각한다.", pron: "아이 띵크 컴퍼니즈 슈드 얼라우 엠플로이이즈 투 츄즈 웨어 데이 원투 웍", keys: [ { en: "allow A to", ko: "A가 ~하도록 허락하다" }, { en: "choose where", ko: "어디서 할지 선택하다" } ] },
  { id: "p5-077", topic: "직장", function: "이유", en: "A friendly work environment makes employees want to stay with the company longer.", ko: "친근한 업무 환경은 직원들이 회사에 더 오래 머물고 싶게 만든다.", pron: "어 프렌들리 웍 인바이런먼트 메익스 엠플로이이즈 원투 스테이 위더 컴퍼니 롱거", keys: [ { en: "work environment", ko: "업무 환경" }, { en: "stay with the company", ko: "회사에 계속 다니다" } ] },
  { id: "p5-078", topic: "교육", function: "의견 시작", en: "Schools should teach practical skills such as managing money and solving problems.", ko: "학교는 돈 관리와 문제 해결 같은 실용적인 기술을 가르쳐야 한다.", pron: "스쿨즈 슈드 티치 프랙티컬 스킬즈 써치 애즈 매니징 머니 앤 솔빙 프라블럼즈", keys: [ { en: "practical skills", ko: "실용적인 기술" }, { en: "such as", ko: "~와 같은" }, { en: "managing money", ko: "돈 관리" } ] },
  { id: "p5-079", topic: "교육", function: "이유", en: "Group projects teach students how to cooperate with people who have different opinions.", ko: "조별 과제는 학생들에게 의견이 다른 사람들과 협력하는 방법을 가르쳐 준다.", pron: "그룹 프라젝츠 티치 스튜던츠 하우 투 코아퍼레잇 위드 피플 후 해브 디퍼런트 오피니언즈", keys: [ { en: "group projects", ko: "조별 과제" }, { en: "how to cooperate with", ko: "~와 협력하는 방법" }, { en: "different opinions", ko: "다른 의견" } ] },
  { id: "p5-080", topic: "기술", function: "이유", en: "Artificial intelligence can handle simple tasks, so workers can focus on more creative work.", ko: "인공지능이 단순한 업무를 처리할 수 있어서 근로자들은 더 창의적인 일에 집중할 수 있다.", pron: "아티피셜 인텔리전스 캔 핸들 심플 태스크스 쏘 워커즈 캔 포커썬 모어 크리에이티브 웍", keys: [ { en: "artificial intelligence", ko: "인공지능" }, { en: "handle simple tasks", ko: "단순한 업무를 처리하다" }, { en: "focus on", ko: "~에 집중하다" } ] },
  { id: "p5-081", topic: "기술", function: "연결", en: "Relying too much on smartphones can make it hard for people to concentrate.", ko: "스마트폰에 너무 의존하면 사람들이 집중하기 어려워질 수 있다.", pron: "릴라잉 투 머치 온 스마트폰즈 캔 메이킷 하드 포 피플 투 칸센트레잇", keys: [ { en: "rely too much on", ko: "~에 너무 의존하다" }, { en: "make it hard for A to", ko: "A가 ~하기 어렵게 만들다" } ] },
  { id: "p5-082", topic: "재택근무", function: "이유", en: "Remote work saves companies money on office rent and utilities.", ko: "원격 근무는 회사가 사무실 임대료와 공과금을 절약하게 해 준다.", pron: "리모트 웍 세이브즈 컴퍼니즈 머니 온 오피스 렌트 앤 유틸리티즈", keys: [ { en: "save A money on", ko: "A가 ~에 드는 돈을 절약하게 하다" }, { en: "office rent", ko: "사무실 임대료" }, { en: "utilities", ko: "공과금" } ] },
  { id: "p5-083", topic: "재택근무", function: "이유", en: "Working from home requires strong self-discipline and good time management skills.", ko: "재택근무에는 강한 자기 관리와 좋은 시간 관리 능력이 필요하다.", pron: "워킹 프럼 홈 리콰이어즈 스트롱 셀프 디서플린 앤 굿 타임 매니지먼트 스킬즈", keys: [ { en: "require", ko: "필요로 하다" }, { en: "self-discipline", ko: "자기 관리, 자제력" }, { en: "time management skills", ko: "시간 관리 능력" } ] },
  { id: "p5-084", topic: "팀워크", function: "이유", en: "When team members trust each other, they can achieve much more than they could alone.", ko: "팀원들이 서로를 신뢰하면 혼자서 할 수 있는 것보다 훨씬 더 많은 것을 이룰 수 있다.", pron: "웬 팀 멤버즈 트러스트 이치 아더 데이 캔 어치브 머치 모어 댄 데이 쿠덜론", keys: [ { en: "trust each other", ko: "서로 신뢰하다" }, { en: "achieve much more", ko: "훨씬 더 많이 이루다" } ] },
  { id: "p5-085", topic: "리더십", function: "의견 시작", en: "A great leader motivates people by setting clear goals and giving honest feedback.", ko: "훌륭한 리더는 명확한 목표를 세우고 솔직한 피드백을 줌으로써 사람들에게 동기를 부여한다.", pron: "어 그레잇 리더 모티베이츠 피플 바이 세팅 클리어 고울즈 앤 기빙 아니스트 피드백", keys: [ { en: "motivate", ko: "동기를 부여하다" }, { en: "set clear goals", ko: "명확한 목표를 세우다" }, { en: "give honest feedback", ko: "솔직한 피드백을 주다" } ] },
  { id: "p5-086", topic: "리더십", function: "의견 시작", en: "Leaders should take responsibility when things go wrong instead of blaming others.", ko: "리더는 일이 잘못되었을 때 남을 탓하는 대신 책임을 져야 한다.", pron: "리더즈 슈드 테익 리스판서빌러티 웬 띵즈 고 롱 인스테더브 블레이밍 아더즈", keys: [ { en: "take responsibility", ko: "책임을 지다" }, { en: "things go wrong", ko: "일이 잘못되다" }, { en: "instead of", ko: "~하는 대신에" } ] },
  { id: "p5-087", topic: "환경", function: "의견 시작", en: "Companies should reduce their use of plastic to help protect the environment.", ko: "회사들은 환경 보호를 돕기 위해 플라스틱 사용을 줄여야 한다.", pron: "컴퍼니즈 슈드 리듀스 데어 유저브 플래스틱 투 헬프 프러텍트 디 인바이런먼트", keys: [ { en: "reduce their use of", ko: "~의 사용을 줄이다" }, { en: "protect the environment", ko: "환경을 보호하다" } ] },
  { id: "p5-088", topic: "환경", function: "의견 시작", en: "Individuals can make a difference by using public transportation and recycling more.", ko: "개인도 대중교통을 이용하고 재활용을 더 많이 함으로써 변화를 만들 수 있다.", pron: "인디비주얼즈 캔 메이커 디퍼런스 바이 유징 퍼블릭 트랜스포테이션 앤 리사이클링 모어", keys: [ { en: "make a difference", ko: "변화를 만들다, 차이를 만들다" }, { en: "recycling", ko: "재활용" } ] },
  { id: "p5-089", topic: "도시 생활", function: "연결", en: "Living in a big city can be expensive, but there are more job opportunities.", ko: "대도시에 사는 것은 비쌀 수 있지만, 일자리 기회가 더 많다.", pron: "리빙 이너 빅 시티 캔 비 익스펜시브 벗 데어라 모어 잡 아퍼튜니티즈", keys: [ { en: "expensive", ko: "비싼" }, { en: "job opportunities", ko: "일자리 기회" } ] },
  { id: "p5-090", topic: "도시 생활", function: "이유", en: "Many people move to the countryside to enjoy a quieter and healthier lifestyle.", ko: "많은 사람들이 더 조용하고 건강한 생활 방식을 즐기기 위해 시골로 이사한다.", pron: "매니 피플 무브 투 더 컨트리사이드 투 인조이 어 콰이어터 앤 헬씨어 라이프스타일", keys: [ { en: "move to the countryside", ko: "시골로 이사하다" }, { en: "healthier lifestyle", ko: "더 건강한 생활 방식" } ] },
  { id: "p5-091", topic: "온라인 학습", function: "이유", en: "Online learning gives people in remote areas access to high-quality education.", ko: "온라인 학습은 외딴 지역의 사람들에게 질 높은 교육을 받을 기회를 준다.", pron: "온라인 러닝 기브즈 피플 인 리모트 에어리어즈 액세스 투 하이 퀄러티 에주케이션", keys: [ { en: "remote areas", ko: "외딴 지역" }, { en: "access to", ko: "~에 대한 접근" }, { en: "high-quality education", ko: "질 높은 교육" } ] },
  { id: "p5-092", topic: "온라인 학습", function: "연결", en: "Some students find it hard to stay motivated without a teacher in the classroom.", ko: "어떤 학생들은 교실에 선생님이 없으면 의욕을 유지하기 어렵다고 느낀다.", pron: "썸 스튜던츠 파인딧 하드 투 스테이 모티베이티드 위다웃 어 티처 인 더 클래스룸", keys: [ { en: "find it hard to", ko: "~하기 어렵다고 느끼다" }, { en: "stay motivated", ko: "의욕을 유지하다" } ] },
  { id: "p5-093", topic: "소셜 미디어", function: "의견 시작", en: "Social media is a powerful tool for small businesses to promote their products.", ko: "소셜 미디어는 소규모 업체들이 제품을 홍보하는 데 강력한 도구이다.", pron: "소셜 미디아 이즈 어 파워풀 툴 포 스몰 비즈니시즈 투 프러모웃 데어 프라덕츠", keys: [ { en: "a powerful tool", ko: "강력한 도구" }, { en: "small businesses", ko: "소규모 업체" }, { en: "promote their products", ko: "제품을 홍보하다" } ] },
  { id: "p5-094", topic: "소셜 미디어", function: "연결", en: "People often compare their lives with others on social media, which can lower their self-esteem.", ko: "사람들은 종종 소셜 미디어에서 자신의 삶을 다른 사람들과 비교하는데, 이는 자존감을 낮출 수 있다.", pron: "피플 오픈 컴페어 데어 라이브즈 위드 아더즈 온 소셜 미디아 위치 캔 로워 데어 셀프 이스팀", keys: [ { en: "compare A with B", ko: "A를 B와 비교하다" }, { en: "lower their self-esteem", ko: "자존감을 낮추다" } ] },
  { id: "p5-095", topic: "진로", function: "의견 시작", en: "When choosing a career, it's important to consider your interests as well as the salary.", ko: "진로를 선택할 때는 연봉뿐만 아니라 자신의 관심사도 고려하는 것이 중요하다.", pron: "웬 츄징 어 커리어 잇츠 임포턴트 투 컨시더 유어 인터레스츠 애즈 웰 애즈 더 샐러리", keys: [ { en: "choosing a career", ko: "진로 선택" }, { en: "consider", ko: "고려하다" }, { en: "as well as", ko: "~뿐만 아니라" } ] },
  { id: "p5-096", topic: "진로", function: "이유", en: "Changing jobs every few years can help people gain a wide range of experience.", ko: "몇 년마다 이직하는 것은 사람들이 폭넓은 경험을 쌓는 데 도움이 될 수 있다.", pron: "체인징 잡스 에브리 퓨 이어즈 캔 헬프 피플 게이너 와이드 레인지 오브 익스피리언스", keys: [ { en: "changing jobs", ko: "이직" }, { en: "every few years", ko: "몇 년마다" }, { en: "a wide range of", ko: "폭넓은" } ] },
  { id: "p5-097", topic: "경영", function: "의견 시작", en: "Managers should involve employees in important decisions that affect their work.", ko: "관리자는 직원들의 업무에 영향을 주는 중요한 결정에 직원들을 참여시켜야 한다.", pron: "매니저즈 슈드 인발브 엠플로이이즈 인 임포턴트 디시전즈 댓 어펙트 데어 웍", keys: [ { en: "involve A in", ko: "A를 ~에 참여시키다" }, { en: "important decisions", ko: "중요한 결정" }, { en: "affect", ko: "영향을 주다" } ] },
  { id: "p5-098", topic: "경영", function: "의견 시작", en: "Giving employees bonuses for good performance is an effective way to boost morale.", ko: "좋은 성과에 대해 직원들에게 보너스를 주는 것은 사기를 높이는 효과적인 방법이다.", pron: "기빙 엠플로이이즈 보너시즈 포 굿 퍼포먼스 이즈 언 이펙티브 웨이 투 부스트 머랠", keys: [ { en: "good performance", ko: "좋은 성과" }, { en: "an effective way to", ko: "~하는 효과적인 방법" }, { en: "boost morale", ko: "사기를 높이다" } ] },
  { id: "p5-099", topic: "고객 서비스", function: "의견 시작", en: "Excellent customer service is often more important than low prices in keeping customers loyal.", ko: "고객의 충성도를 유지하는 데에는 훌륭한 고객 서비스가 낮은 가격보다 더 중요한 경우가 많다.", pron: "엑설런트 커스터머 서비스 이즈 오픈 모어 임포턴트 댄 로우 프라이시즈 인 키핑 커스터머즈 로열", keys: [ { en: "customer service", ko: "고객 서비스" }, { en: "low prices", ko: "낮은 가격" }, { en: "keeping customers loyal", ko: "고객의 충성도를 유지하기" } ] },
  { id: "p5-100", topic: "고객 서비스", function: "의견 시작", en: "Companies should respond to customer complaints quickly to show that they really care.", ko: "회사는 진심으로 신경 쓰고 있음을 보여 주기 위해 고객 불만에 신속하게 대응해야 한다.", pron: "컴퍼니즈 슈드 리스판투 커스터머 컴플레인츠 퀵클리 투 쇼우 댓 데이 리얼리 케어", keys: [ { en: "respond to", ko: "~에 대응하다" }, { en: "customer complaints", ko: "고객 불만" }, { en: "really care", ko: "진심으로 신경 쓰다" } ] },
  { id: "p5-101", topic: "리더십", function: "의견 시작", en: "The most important quality for a leader is communication skills.", ko: "리더에게 가장 중요한 자질은 의사소통 능력이다.", pron: "더 모스트 임포턴트 퀄러티 포 어 리더 이즈 커뮤니케이션 스킬즈", keys: [ { en: "The most important quality for a leader is", ko: "리더에게 가장 중요한 자질은 ~이다 (질문 문장을 그대로 받아요)" }, { en: "communication skills", ko: "의사소통 능력" } ] },
  { id: "p5-102", topic: "팀워크", function: "의견 시작", en: "When it comes to teamwork, communication skills are the most important.", ko: "팀워크에 관해서라면 의사소통 능력이 가장 중요하다.", pron: "웬 잇 컴즈 투 팀웍 커뮤니케이션 스킬즈 아 더 모스트 임포턴트", keys: [ { en: "When it comes to", ko: "~에 관해서라면 (범위를 좁혀 말할 때)" } ] },
  { id: "p5-103", topic: "리더십", function: "이유", en: "It can increase work efficiency.", ko: "그것은 업무 효율을 높일 수 있다.", pron: "잇 캔 인크리스 웍 이피션시", keys: [ { en: "increase work efficiency", ko: "업무 효율을 높이다" } ] },
  { id: "p5-104", topic: "팀워크", function: "이유", en: "It's essential for teamwork.", ko: "그것은 팀워크에 꼭 필요하다.", pron: "잇츠 이센셜 포 팀웍", keys: [ { en: "essential for", ko: "~에 꼭 필요한" } ] },
  { id: "p5-105", topic: "환경", function: "이유", en: "First, it will be good for the environment.", ko: "첫째, 그것은 환경에 좋을 것이다.", pron: "퍼스트 이릴 비 굿 포 디 인바이런먼트", keys: [ { en: "good for the environment", ko: "환경에 좋은 (environment 앞에 the)" } ] },
  { id: "p5-106", topic: "환경", function: "이유", en: "As you know, climate change is a serious problem.", ko: "알다시피 기후 변화는 심각한 문제다.", pron: "애즈 유 노우 클라이밋 체인지 이즈 어 시리어스 프라블럼", keys: [ { en: "As you know,", ko: "알다시피" }, { en: "climate change", ko: "기후 변화" } ] },
  { id: "p5-107", topic: "환경", function: "예시", en: "If people pay an extra fee, they will use their own bags.", ko: "사람들이 추가 요금을 내야 한다면 자기 가방을 쓸 것이다.", pron: "이프 피플 페이 언 엑스트라 피 데이 윌 유즈 데어 오운 백즈", keys: [ { en: "If + 주어 + 동사, 주어 + will/can + 동사", ko: "~하면 ~할 것이다 (근거를 만드는 공식)" }, { en: "extra fee", ko: "추가 요금" } ] },
  { id: "p5-108", topic: "환경", function: "예시", en: "Then we can decrease the use of plastic bags.", ko: "그러면 우리는 비닐봉지 사용을 줄일 수 있다.", pron: "덴 위 캔 디크리스 더 유스 오브 플라스틱 백즈", keys: [ { en: "Then we can", ko: "그러면 우리는 ~할 수 있다 (결과를 한 번 더)" }, { en: "plastic bags", ko: "비닐봉지" } ] },
  { id: "p5-109", topic: "환경", function: "결론", en: "As a result, it will be beneficial for our society.", ko: "결과적으로 그것은 우리 사회에 이로울 것이다.", pron: "애저 리절트 이릴 비 베너피셜 포 아워 소사이어티", keys: [ { en: "As a result,", ko: "결과적으로" }, { en: "beneficial for", ko: "~에 이로운" } ] },
  { id: "p5-110", topic: "직장", function: "이유", en: "They will be satisfied with the work environment.", ko: "그들은 근무 환경에 만족할 것이다.", pron: "데이 윌 비 새티스파이드 위드 더 웍 인바이런먼트", keys: [ { en: "be satisfied with", ko: "~에 만족하다" }, { en: "work environment", ko: "근무 환경" } ] },
  { id: "p5-111", topic: "직장", function: "예시", en: "If employees have flexible work hours, they can work more efficiently.", ko: "직원들에게 유연 근무 시간이 있으면 더 효율적으로 일할 수 있다.", pron: "이프 엠플로이이즈 해브 플렉서블 웍 아워즈 데이 캔 웍 모어 이피션틀리", keys: [ { en: "flexible work hours", ko: "유연 근무 시간" }, { en: "work more efficiently", ko: "더 효율적으로 일하다" } ] },
  { id: "p5-112", topic: "팀워크", function: "결론", en: "Eventually, it will be beneficial for the team.", ko: "결국 그것은 팀에 이로울 것이다.", pron: "이벤추얼리 이릴 비 베너피셜 포 더 팀", keys: [ { en: "Eventually,", ko: "결국" } ] },
  { id: "p5-113", topic: "조언", function: "이유", en: "They know me well.", ko: "그들은 나를 잘 안다.", pron: "데이 노우 미 웰", keys: [ { en: "know me well", ko: "나를 잘 알다 (가까운 사람에게 조언을 구하는 이유)" } ] },
  { id: "p5-114", topic: "조언", function: "이유", en: "They are honest and I can trust them.", ko: "그들은 정직하고 나는 그들을 믿을 수 있다.", pron: "데이아 아너스트 앤 아이 캔 트러스트 뎀", keys: [ { en: "honest", ko: "정직한, 솔직한" }, { en: "trust", ko: "믿다" } ] },
  { id: "p5-115", topic: "스트레스", function: "이유", en: "It will be fun and interesting.", ko: "그것은 재미있고 흥미로울 것이다.", pron: "이릴 비 펀 앤 인터레스팅", keys: [ { en: "fun and interesting", ko: "재미있고 흥미로운" } ] },
  { id: "p5-116", topic: "스트레스", function: "이유", en: "Then they can get rid of stress.", ko: "그러면 그들은 스트레스를 풀 수 있다.", pron: "덴 데이 캔 겟 리드 오브 스트레스", keys: [ { en: "get rid of stress", ko: "스트레스를 풀다(없애다)" } ] },
  { id: "p5-117", topic: "가치관", function: "이유", en: "It makes me happy.", ko: "그것은 나를 행복하게 한다.", pron: "잇 메익스 미 해피", keys: [ { en: "make me happy", ko: "나를 행복하게 하다" } ] },
  { id: "p5-118", topic: "가치관", function: "이유", en: "I think it's worth the money.", ko: "나는 그것이 돈을 쓸 만한 가치가 있다고 생각한다.", pron: "아이 띵크 잇츠 워쓰 더 머니", keys: [ { en: "worth the money", ko: "돈을 쓸 만한 가치가 있는" } ] },
  { id: "p5-119", topic: "성공", function: "예시", en: "My uncle is a singer, and he says talent is not enough.", ko: "우리 삼촌은 가수인데, 재능만으로는 충분하지 않다고 말한다.", pron: "마이 엉클 이즈 어 싱어 앤 히 세즈 탤런트 이즈 낫 이너프", keys: [ { en: "he says", ko: "그는 ~라고 말한다 (주변 사람의 말을 근거로)" }, { en: "talent is not enough", ko: "재능만으로는 충분하지 않다" } ] },
  { id: "p5-120", topic: "이유", function: "이유", en: "Above all, it can save time and money.", ko: "무엇보다 그것은 시간과 돈을 아낄 수 있다.", pron: "어버브 올 잇 캔 세이브 타임 앤 머니", keys: [ { en: "Above all,", ko: "무엇보다 (Most of all도 같은 뜻)" }, { en: "save time and money", ko: "시간과 돈을 아끼다" } ] },
  { id: "p5-121", topic: "교육", function: "의견 시작", en: "Students should be allowed to choose their courses.", ko: "학생들이 수강할 과목을 직접 선택할 수 있어야 한다.", pron: "스튜던츠 슈드 비 얼라우드 투 추즈 데어 코시즈", keys: [ { en: "should be allowed to", ko: "~할 수 있도록 허용되어야 한다" }, { en: "choose their courses", ko: "수강할 과목을 선택하다" } ] },
  { id: "p5-122", topic: "스트레스", function: "이유", en: "Having a hobby unrelated to work is fun and interesting.", ko: "일과 무관한 취미를 갖는 것은 재미있고 흥미롭다.", pron: "해빙 어 하비 언릴레이티드 투 워크 이즈 펀 앤 인터레스팅", keys: [ { en: "a hobby unrelated to work", ko: "일과 무관한 취미" }, { en: "fun and interesting", ko: "재미있고 흥미로운" } ] },
  { id: "p5-123", topic: "성공", function: "예시", en: "A famous singer says that talent is not enough without practice.", ko: "한 유명한 가수는 연습 없이는 재능만으로 충분하지 않다고 말한다.", pron: "어 페이머스 싱어 세즈 댓 탤런트 이즈 낫 이너프 위다웃 프랙티스", keys: [ { en: "A famous singer says that", ko: "한 유명한 가수가 ~라고 말한다" }, { en: "without practice", ko: "연습 없이는" } ] },
  { id: "p5-124", topic: "교육", function: "이유", en: "Most of all, students have a lot of schoolwork to do these days.", ko: "무엇보다 요즘 학생들은 해야 할 학교 공부가 많다.", pron: "모스트 어브 올 스튜던츠 해브 어 랏 어브 스쿨워크 투 두 디즈 데이즈", keys: [ { en: "Most of all,", ko: "무엇보다" }, { en: "a lot of schoolwork", ko: "많은 학교 공부" }, { en: "these days", ko: "요즘" } ] },
  { id: "p5-125", topic: "교육", function: "의견 시작", en: "I think teachers who assign homework each day are better.", ko: "나는 매일 숙제를 내주는 선생님이 더 좋다고 생각한다.", pron: "아이 띵크 티처즈 후 어사인 홈워크 이치 데이 아 베터", keys: [ { en: "teachers who assign homework", ko: "숙제를 내주는 선생님들" }, { en: "each day", ko: "매일" } ] },
  { id: "p5-126", topic: "교육", function: "이유", en: "It will encourage students to study and work hard after class.", ko: "그것은 학생들이 수업 후에도 공부하고 열심히 노력하도록 이끌 것이다.", pron: "잇 윌 인커리지 스튜던츠 투 스터디 앤 워크 하드 애프터 클래스", keys: [ { en: "encourage students to", ko: "학생들이 ~하도록 이끌다" }, { en: "after class", ko: "수업 후에" } ] },
  { id: "p5-127", topic: "교육", function: "연결", en: "As a result, they can get good grades.", ko: "결과적으로 그들은 좋은 성적을 받을 수 있다.", pron: "애즈 어 리절트 데이 캔 겟 굿 그레이즈", keys: [ { en: "As a result,", ko: "결과적으로" }, { en: "get good grades", ko: "좋은 성적을 받다" } ] },
  { id: "p5-128", topic: "교육", function: "예시", en: "For example, when I was in high school, my homeroom teacher gave us homework every day.", ko: "예를 들어 내가 고등학교에 다닐 때 담임 선생님은 우리에게 매일 숙제를 내주셨다.", pron: "포 이그잼플 웬 아이 워즈 인 하이 스쿨 마이 홈룸 티처 게이브 어스 홈워크 에브리 데이", keys: [ { en: "when I was in high school", ko: "내가 고등학교에 다닐 때" }, { en: "my homeroom teacher", ko: "내 담임 선생님" }, { en: "gave us homework", ko: "우리에게 숙제를 내줬다" } ] },
  { id: "p5-129", topic: "교육", function: "예시", en: "At first, my classmates and I didn't like it, but gradually, our performance got better.", ko: "처음에는 반 친구들과 나 모두 그것을 좋아하지 않았지만 점차 학업 성과가 좋아졌다.", pron: "앳 퍼스트 마이 클래스메이츠 앤 아이 디든트 라이크 잇 벗 그래쥬얼리 아워 퍼포먼스 갓 베터", keys: [ { en: "At first,", ko: "처음에는" }, { en: "my classmates and I", ko: "반 친구들과 나" }, { en: "gradually", ko: "점차" }, { en: "our performance got better", ko: "우리의 학업 성과가 좋아졌다" } ] },
  { id: "p5-130", topic: "의견 시작", function: "의견 시작", en: "I will give reasons and examples to support my opinion.", ko: "내 의견을 뒷받침할 이유와 예를 들어 보겠다.", pron: "아이 윌 기브 리즌즈 앤 이그잼플즈 투 서포트 마이 오피니언", keys: [ { en: "give reasons and examples", ko: "이유와 예를 들다" }, { en: "support my opinion", ko: "내 의견을 뒷받침하다" } ] },
  { id: "p5-131", topic: "의견 시작", function: "의견 시작", en: "If I had to choose between the two options, I would choose the first one.", ko: "두 가지 선택지 중에서 골라야 한다면 나는 첫 번째를 고르겠다.", pron: "이프 아이 해투 츄즈 비트윈 더 투 압션즈 아이 우드 츄즈 더 퍼스트 원", keys: [ { en: "between the two options", ko: "두 가지 선택지 중에서" }, { en: "choose the first one", ko: "첫 번째 것을 고르다" } ] },
  { id: "p5-132", topic: "의견 시작", function: "의견 시작", en: "I agree with the statement that practical experience is more valuable than theory.", ko: "나는 이론보다 실무 경험이 더 가치 있다는 주장에 동의한다.", pron: "아이 어그리 위더 스테잇먼트 댓 프랙티컬 익스피리언스 이즈 모어 밸류어블 댄 씨어리", keys: [ { en: "agree with the statement that", ko: "~라는 주장에 동의하다" }, { en: "more valuable than", ko: "~보다 더 가치 있는" } ] },
  { id: "p5-133", topic: "의견 시작", function: "의견 시작", en: "Personally, I think it is better to work for a company that values employee growth.", ko: "개인적으로 나는 직원의 성장을 중시하는 회사에서 일하는 것이 더 낫다고 생각한다.", pron: "퍼스널리 아이 띵크 잇 이즈 베러 투 웍 포 어 컴퍼니 댓 밸류즈 엠플로이 그로쓰", keys: [ { en: "values", ko: "중시하다, 가치 있게 여기다" }, { en: "employee growth", ko: "직원의 성장" } ] },
  { id: "p5-134", topic: "의견 시작", function: "의견 시작", en: "In my opinion, the best way to learn a new skill is by practicing it every day.", ko: "내 생각에는 새로운 기술을 배우는 가장 좋은 방법은 매일 연습하는 것이다.", pron: "인 마이 오피니언 더 베스트 웨이 투 런 어 뉴 스킬 이즈 바이 프랙티싱 잇 에브리 데이", keys: [ { en: "the best way to", ko: "~하는 가장 좋은 방법" }, { en: "by practicing", ko: "연습함으로써" } ] },
  { id: "p5-135", topic: "의견 시작", function: "의견 시작", en: "I strongly believe that clear communication is the foundation of a successful team.", ko: "나는 명확한 의사소통이 성공적인 팀의 기초라고 강력히 믿는다.", pron: "아이 스트롱리 빌리브 댓 클리어 커뮤니케이션 이즈 더 파운데이션 오브 어 석세스풀 팀", keys: [ { en: "clear communication", ko: "명확한 의사소통" }, { en: "the foundation of", ko: "~의 기초, 토대" } ] },
  { id: "p5-136", topic: "이유", function: "이유", en: "First of all, it helps people save energy and focus on their main tasks.", ko: "무엇보다도 그것은 사람들이 에너지를 아끼고 주요 업무에 집중하도록 돕는다.", pron: "퍼스트 오브 올 잇 헬프스 피플 세이브 에너지 앤 포커썬 데어 메인 태스크스", keys: [ { en: "save energy", ko: "에너지를 아끼다" }, { en: "main tasks", ko: "주요 업무" } ] },
  { id: "p5-137", topic: "이유", function: "이유", en: "Another reason is that it reduces unnecessary mistakes and saves a lot of time.", ko: "또 다른 이유는 불필요한 실수를 줄이고 많은 시간을 아껴 준다는 것이다.", pron: "어나더 리즌 이즈 댓 잇 리듀시즈 언네서세리 미스테익스 앤 세이브즈 얼라러브 타임", keys: [ { en: "unnecessary mistakes", ko: "불필요한 실수" }, { en: "saves a lot of time", ko: "많은 시간을 아껴 주다" } ] },
  { id: "p5-138", topic: "이유", function: "이유", en: "Most importantly, people can make better decisions when they have enough information.", ko: "가장 중요한 것은, 충분한 정보가 있을 때 사람들이 더 나은 결정을 내릴 수 있다는 점이다.", pron: "모스트 임포턴틀리 피플 캔 메익 베러 디시전즈 웬 데이 해브 이너프 인포메이션", keys: [ { en: "make better decisions", ko: "더 나은 결정을 내리다" }, { en: "enough information", ko: "충분한 정보" } ] },
  { id: "p5-139", topic: "이유", function: "이유", en: "This is because people work much harder when they feel respected and supported.", ko: "이는 사람들이 존중받고 지원받는다고 느낄 때 훨씬 더 열심히 일하기 때문이다.", pron: "디스 이즈 비코즈 피플 웍 머치 하더 웬 데이 필 리스펙티드 앤 서포티드", keys: [ { en: "work much harder", ko: "훨씬 더 열심히 일하다" }, { en: "feel respected", ko: "존중받는다고 느끼다" } ] },
  { id: "p5-140", topic: "이유", function: "이유", en: "One of the biggest benefits is that we can learn from other people's experiences.", ko: "가장 큰 이점 중 하나는 다른 사람들의 경험에서 배울 수 있다는 것이다.", pron: "워너브 더 비기스트 베니핏츠 이즈 댓 위 캔 런 프럼 아더 피플즈 익스피리언시즈", keys: [ { en: "One of the biggest benefits", ko: "가장 큰 이점 중 하나" }, { en: "learn from", ko: "~로부터 배우다" } ] },
  { id: "p5-141", topic: "이유", function: "이유", en: "Since everyone has different strengths, working together produces better results.", ko: "모든 사람이 서로 다른 강점을 가지고 있기 때문에 함께 일하면 더 좋은 결과를 낸다.", pron: "씬스 에브리원 해즈 디퍼런트 스트렝쓰스 워킹 투게더 프러듀시즈 베러 리절츠", keys: [ { en: "different strengths", ko: "서로 다른 강점" }, { en: "produces better results", ko: "더 좋은 결과를 내다" } ] },
  { id: "p5-142", topic: "예시", function: "예시", en: "For example, in my case, I always write down my daily goals before starting work.", ko: "예를 들어 내 경우에는 일을 시작하기 전에 항상 하루 목표를 적어 둔다.", pron: "포 이그잼플 인 마이 케이스 아이 올웨이즈 라잇 다운 마이 데일리 고울즈 비포 스타팅 웍", keys: [ { en: "For example, in my case,", ko: "예를 들어 내 경우에는" }, { en: "daily goals", ko: "하루 목표" } ] },
  { id: "p5-143", topic: "예시", function: "예시", en: "When I worked on a big project last year, my mentor gave me very helpful advice.", ko: "작년에 큰 프로젝트를 맡았을 때 멘토가 나에게 매우 도움이 되는 조언을 해 주었다.", pron: "웬 아이 웍트 온 어 빅 프라젝트 래스트 이어 마이 멘토 게이브 미 베리 헬프풀 어드바이스", keys: [ { en: "worked on a big project", ko: "큰 프로젝트를 맡아 일했다" }, { en: "helpful advice", ko: "도움이 되는 조언" } ] },
  { id: "p5-144", topic: "예시", function: "예시", en: "For instance, my older sister took an evening class and got a better job six months later.", ko: "예를 들어 우리 언니(누나)는 야간 수업을 듣고 6개월 뒤에 더 좋은 직장을 얻었다.", pron: "포 인스턴스 마이 올더 시스터 툭 언 이브닝 클래스 앤 갓 어 베러 잡 식스 먼쓰 레이터", keys: [ { en: "evening class", ko: "야간 수업" }, { en: "six months later", ko: "6개월 뒤에" } ] },
  { id: "p5-145", topic: "예시", function: "예시", en: "In my case, when I was in college, I learned how to manage my time through a part-time job.", ko: "내 경우에는 대학 시절 아르바이트를 통해 시간 관리하는 법을 배웠다.", pron: "인 마이 케이스 웬 아이 워즈 인 칼리지 아이 런드 하우 투 매니지 마이 타임 쓰루 어 파트타임 잡", keys: [ { en: "manage my time", ko: "시간을 관리하다" }, { en: "part-time job", ko: "아르바이트, 시간제 일자리" } ] },
  { id: "p5-146", topic: "예시", function: "예시", en: "My company recently introduced a four-day workweek once a month, and employees love it.", ko: "우리 회사는 최근 한 달에 한 번 주 4일 근무제를 도입했는데 직원들이 매우 좋아한다.", pron: "마이 컴퍼니 리슨틀리 인트러듀스트 어 포데이 웍윅 원스 어 먼쓰 앤 엠플로이이즈 러브 잇", keys: [ { en: "introduced", ko: "도입했다" }, { en: "four-day workweek", ko: "주 4일 근무제" } ] },
  { id: "p5-147", topic: "예시", function: "예시", en: "A few years ago, I started exercising every morning, and my energy level improved a lot.", ko: "몇 년 전 나는 매일 아침 운동을 시작했고 에너지 수준이 많이 좋아졌다.", pron: "어 퓨 이어즈 어고우 아이 스타티드 엑서사이징 에브리 모닝 앤 마이 에너지 레벨 임프루브드 얼랏", keys: [ { en: "energy level", ko: "에너지 수준, 활력" }, { en: "improved a lot", ko: "많이 향상되었다" } ] },
  { id: "p5-148", topic: "연결", function: "연결", en: "As a result, employees can focus better on their work and make fewer mistakes.", ko: "결과적으로 직원들은 업무에 더 잘 집중하고 실수를 덜 할 수 있다.", pron: "애저 리절트 엠플로이이즈 캔 포커스 베러 온 데어 웍 앤 메익 퓨어 미스테익스", keys: [ { en: "focus better on", ko: "~에 더 잘 집중하다" }, { en: "make fewer mistakes", ko: "실수를 덜 하다" } ] },
  { id: "p5-149", topic: "연결", function: "연결", en: "However, we also need clear rules so that everyone works toward the same goal.", ko: "하지만 모두가 같은 목표를 향해 일할 수 있도록 명확한 규칙도 필요하다.", pron: "하우에버 위 올소 니드 클리어 룰즈 쏘 댓 에브리원 웍스 투워드 더 세임 고울", keys: [ { en: "clear rules", ko: "명확한 규칙" }, { en: "so that", ko: "~할 수 있도록" }, { en: "the same goal", ko: "같은 목표" } ] },
  { id: "p5-150", topic: "연결", function: "연결", en: "On the other hand, working alone is sometimes faster when the task is simple.", ko: "반면에 업무가 단순할 때는 혼자 일하는 것이 때로 더 빠르다.", pron: "온 디 아더 핸드 워킹 얼론 이즈 썸타임즈 패스터 웬 더 태스크 이즈 심플", keys: [ { en: "On the other hand,", ko: "반면에" }, { en: "when the task is simple", ko: "업무가 단순할 때" } ] },
  { id: "p5-151", topic: "연결", function: "연결", en: "Because of this, many people now prefer flexible schedules over a higher salary.", ko: "이 때문에 이제 많은 사람들이 더 높은 연봉보다 유연한 근무 일정을 선호한다.", pron: "비코저브 디스 매니 피플 나우 프리퍼 플렉서블 스케줄즈 오버 어 하이어 샐러리", keys: [ { en: "Because of this,", ko: "이 때문에" }, { en: "prefer A over B", ko: "B보다 A를 선호하다" } ] },
  { id: "p5-152", topic: "연결", function: "연결", en: "Even though it takes time at first, it will bring great benefits in the long run.", ko: "비록 처음에는 시간이 걸리지만 장기적으로는 큰 이점을 가져다줄 것이다.", pron: "이븐 도우 잇 테익스 타임 앳 퍼스트 이릴 브링 그레잇 베니핏츠 인 더 롱 런", keys: [ { en: "at first", ko: "처음에는" }, { en: "in the long run", ko: "장기적으로, 결국에는" } ] },
  { id: "p5-153", topic: "연결", function: "연결", en: "Although new technology is convenient, face-to-face communication is still necessary.", ko: "비록 새로운 기술이 편리하지만 대면 의사소통은 여전히 필요하다.", pron: "올도우 뉴 테크날러지 이즈 컨비니언트 페이스 투 페이스 커뮤니케이션 이즈 스틸 네서세리", keys: [ { en: "Although", ko: "비록 ~이지만" }, { en: "face-to-face communication", ko: "대면 의사소통" } ] },
  { id: "p5-154", topic: "결론", function: "결론", en: "That's why I strongly believe that practical training is essential for new employees.", ko: "그래서 나는 신입 직원들에게 실무 교육이 필수적이라고 강력히 믿는다.", pron: "댓츠 와이 아이 스트롱리 빌리브 댓 프랙티컬 트레이닝 이즈 이센셜 포 뉴 엠플로이이즈", keys: [ { en: "practical training", ko: "실무 교육" }, { en: "new employees", ko: "신입 직원들" } ] },
  { id: "p5-155", topic: "결론", function: "결론", en: "For these reasons, I think having a balanced lifestyle is the most important thing.", ko: "이러한 이유로 나는 균형 잡힌 생활 방식을 갖는 것이 가장 중요하다고 생각한다.", pron: "포 디즈 리즌즈 아이 띵크 해빙 어 밸런스트 라이프스타일 이즈 더 모스트 임포턴트 띵", keys: [ { en: "For these reasons,", ko: "이러한 이유로" }, { en: "balanced lifestyle", ko: "균형 잡힌 생활 방식" } ] },
  { id: "p5-156", topic: "결론", function: "결론", en: "Therefore, companies and individuals should work together to solve this problem.", ko: "따라서 기업과 개인이 이 문제를 해결하기 위해 함께 노력해야 한다.", pron: "데어포어 컴퍼니즈 앤 인디비주얼즈 슈드 웍 투게더 투 솔브 디스 프라블럼", keys: [ { en: "work together", ko: "함께 일하다(노력하다)" }, { en: "solve this problem", ko: "이 문제를 해결하다" } ] },
  { id: "p5-157", topic: "결론", function: "결론", en: "In conclusion, choosing the right career path requires careful thought and preparation.", ko: "결론적으로 올바른 진로를 선택하는 데에는 신중한 고민과 준비가 필요하다.", pron: "인 컨클루전 츄징 더 라잇 커리어 패쓰 리콰이어즈 케어풀 톳 앤 프레퍼레이션", keys: [ { en: "career path", ko: "진로" }, { en: "careful thought", ko: "신중한 생각(고민)" } ] },
  { id: "p5-158", topic: "결론", function: "결론", en: "To sum up, a supportive work culture benefits both workers and the organization.", ko: "요약하자면, 서로 돕는 직장 문화는 근로자와 조직 모두에게 이롭다.", pron: "투 써멉 어 서포티브 웍 컬쳐 베니핏츠 보쓰 워커즈 앤 디 오거나이제이션", keys: [ { en: "supportive work culture", ko: "서로 돕는 직장 문화" }, { en: "organization", ko: "조직, 회사" } ] },
  { id: "p5-159", topic: "결론", function: "결론", en: "So, overall, I think investing in education is the best choice for the future.", ko: "그래서 전반적으로 나는 교육에 투자하는 것이 미래를 위한 최선의 선택이라고 생각한다.", pron: "쏘 오버롤 아이 띵크 인베스팅 인 에주케이션 이즈 더 베스트 쵸이스 포 더 퓨쳐", keys: [ { en: "investing in education", ko: "교육에 투자하는 것" }, { en: "for the future", ko: "미래를 위해" } ] },
  { id: "p5-160", topic: "직장", function: "의견 시작", en: "I believe companies should allow employees to wear casual clothes at the office.", ko: "나는 회사가 직원들에게 사무실에서 자율 복장을 입도록 허용해야 한다고 믿는다.", pron: "아이 빌리브 컴퍼니즈 슈드 얼라우 엠플로이이즈 투 웨어 캐쥬얼 클로우즈 앳 디 오피스", keys: [ { en: "wear casual clothes", ko: "자율 복장(편한 옷)을 입다" }, { en: "at the office", ko: "사무실에서" } ] },
  { id: "p5-161", topic: "직장", function: "이유", en: "First of all, comfortable clothes help employees feel relaxed and think more creatively.", ko: "무엇보다도 편안한 복장은 직원들이 긴장을 풀고 더 창의적으로 생각하도록 도와준다.", pron: "퍼스트 오브 올 컴퍼터블 클로우즈 헬프 엠플로이이즈 필 릴랙스트 앤 띵크 모어 크리에이티블리", keys: [ { en: "comfortable clothes", ko: "편안한 옷" }, { en: "think more creatively", ko: "더 창의적으로 생각하다" } ] },
  { id: "p5-162", topic: "직장", function: "이유", en: "Another reason is that a mentorship program helps new hires adapt to the company quickly.", ko: "또 다른 이유는 멘토링 프로그램이 신입 사원들이 회사에 빨리 적응하도록 돕는다는 것이다.", pron: "어나더 리즌 이즈 댓 어 멘토쉽 프로그램 헬프스 뉴 하이어즈 어댑투 더 컴퍼니 퀵클리", keys: [ { en: "mentorship program", ko: "멘토링 프로그램" }, { en: "new hires", ko: "신입 사원들" }, { en: "adapt to", ko: "~에 적응하다" } ] },
  { id: "p5-163", topic: "직장", function: "예시", en: "For example, my company provides free healthy snacks and a quiet lounge for employees.", ko: "예를 들어 우리 회사는 직원들에게 무료 건강 간식과 조용한 휴게실을 제공한다.", pron: "포 이그잼플 마이 컴퍼니 프러바이즈 프리 헬씨 스낵스 앤 어 콰이엇 라운지 포 엠플로이이즈", keys: [ { en: "healthy snacks", ko: "건강한 간식" }, { en: "quiet lounge", ko: "조용한 휴게실" } ] },
  { id: "p5-164", topic: "직장", function: "연결", en: "As a result, job satisfaction goes up and fewer employees leave the company.", ko: "결과적으로 직무 만족도가 올라가고 회사를 떠나는 직원이 줄어든다.", pron: "애저 리절트 잡 새티스팩션 고우즈 업 앤 퓨어 엠플로이이즈 리브 더 컴퍼니", keys: [ { en: "job satisfaction", ko: "직무 만족도" }, { en: "leave the company", ko: "회사를 떠나다(퇴사하다)" } ] },
  { id: "p5-165", topic: "직장", function: "결론", en: "That's why I think a comfortable workplace is essential for high productivity.", ko: "그래서 나는 높은 생산성을 위해 편안한 업무 공간이 필수적이라고 생각한다.", pron: "댓츠 와이 아이 띵크 어 컴퍼터블 웍플레이스 이즈 이센셜 포 하이 프러덕티비티", keys: [ { en: "comfortable workplace", ko: "편안한 업무 공간" }, { en: "high productivity", ko: "높은 생산성" } ] },
  { id: "p5-166", topic: "교육", function: "의견 시작", en: "I think schools should spend more time teaching financial literacy and cooking skills.", ko: "나는 학교가 금융 지식과 요리 기술을 가르치는 데 더 많은 시간을 써야 한다고 생각한다.", pron: "아이 띵크 스쿨즈 슈드 스펜드 모어 타임 티칭 파이낸셜 리터러시 앤 쿠킹 스킬즈", keys: [ { en: "financial literacy", ko: "금융 이해력(경제 지식)" }, { en: "cooking skills", ko: "요리 기술" } ] },
  { id: "p5-167", topic: "교육", function: "이유", en: "First of all, these practical skills are useful for the rest of our lives after graduation.", ko: "무엇보다도 이러한 실용적인 기술은 졸업 후 남은 평생 동안 유용하다.", pron: "퍼스트 오브 올 디즈 프랙티컬 스킬즈 아 유스풀 포 더 레스트 오브 아워 라이브즈 애프터 그래쥬에이션", keys: [ { en: "for the rest of our lives", ko: "남은 평생 동안" }, { en: "after graduation", ko: "졸업 후에" } ] },
  { id: "p5-168", topic: "교육", function: "이유", en: "Another reason is that field trips allow students to see how knowledge is used in real life.", ko: "또 다른 이유는 현장 학습이 학생들에게 지식이 실제 생활에서 어떻게 쓰이는지 보게 해 준다는 것이다.", pron: "어나더 리즌 이즈 댓 필드 트립스 얼라우 스튜던츠 투 씨 하우 날리지 이즈 유즈드 인 리얼 라이프", keys: [ { en: "field trips", ko: "현장 학습, 견학" }, { en: "in real life", ko: "실제 생활에서" } ] },
  { id: "p5-169", topic: "교육", function: "예시", en: "For instance, when I was in high school, I learned basic cooking in a home economics class.", ko: "예를 들어 내가 고등학교에 다닐 때 가정 수업 시간에 기초 요리를 배웠다.", pron: "포 인스턴스 웬 아이 워즈 인 하이 스쿨 아이 런드 베이직 쿠킹 이너 홈 이카나믹스 클래스", keys: [ { en: "basic cooking", ko: "기초 요리" }, { en: "home economics class", ko: "가정 수업" } ] },
  { id: "p5-170", topic: "교육", function: "연결", en: "Because of this, I can now cook healthy meals for myself while living on my own.", ko: "이 덕분에 나는 지금 혼자 살면서도 스스로 건강한 식사를 만들어 먹을 수 있다.", pron: "비코저브 디스 아이 캔 나우 쿡 헬씨 밀즈 포 마이셀프 와일 리빙 온 마이 오운", keys: [ { en: "healthy meals", ko: "건강한 식사" }, { en: "living on my own", ko: "혼자 사는 것(자취)" } ] },
  { id: "p5-171", topic: "교육", function: "결론", en: "Therefore, I believe hands-on education prepares students better for the real world.", ko: "따라서 나는 체험 중심 교육이 학생들을 실제 사회에 더 잘 대비시켜 준다고 믿는다.", pron: "데어포어 아이 빌리브 핸즈온 에주케이션 프리페어즈 스튜던츠 베러 포 더 리얼 월드", keys: [ { en: "hands-on education", ko: "체험 중심 교육, 실습 교육" }, { en: "the real world", ko: "실제 사회, 현실 세계" } ] },
  { id: "p5-172", topic: "기술", function: "의견 시작", en: "I think people should limit their screen time in the evening to improve their health.", ko: "나는 건강을 개선하기 위해 사람들이 저녁 시간에 화면 보는 시간을 줄여야 한다고 생각한다.", pron: "아이 띵크 피플 슈드 리밋 데어 스크린 타임 인 디 이브닝 투 임프루브 데어 헬쓰", keys: [ { en: "limit their screen time", ko: "화면 보는 시간을 제한하다" }, { en: "improve their health", ko: "건강을 개선하다" } ] },
  { id: "p5-173", topic: "기술", function: "이유", en: "The main reason is that using digital devices late at night harms our sleep quality.", ko: "주된 이유는 밤늦게 디지털 기기를 사용하는 것이 수면의 질을 해친다는 것이다.", pron: "더 메인 리즌 이즈 댓 유징 디지털 디바이시즈 레잇 앳 나잇 함즈 아워 슬립 퀄러티", keys: [ { en: "digital devices", ko: "디지털 기기" }, { en: "sleep quality", ko: "수면의 질" } ] },
  { id: "p5-174", topic: "기술", function: "예시", en: "In my case, when I stopped checking my phone in bed, I fell asleep much faster.", ko: "내 경우에는 침대에서 휴대폰 확인하는 것을 그만두었을 때 훨씬 더 빨리 잠들었다.", pron: "인 마이 케이스 웬 아이 스탑트 체킹 마이 폰 인 베드 아이 펠 어슬립 머치 패스터", keys: [ { en: "stopped checking my phone", ko: "휴대폰 확인하는 것을 멈췄다" }, { en: "fell asleep", ko: "잠들었다" } ] },
  { id: "p5-175", topic: "기술", function: "이유", en: "Thanks to cloud tools, our team members can edit the same document at the same time.", ko: "클라우드 도구 덕분에 우리 팀원들은 동시에 같은 문서를 편집할 수 있다.", pron: "쌩스 투 클라우드 툴즈 아워 팀 멤버즈 캔 에딧 더 세임 다큐먼트 앳 더 세임 타임", keys: [ { en: "cloud tools", ko: "클라우드 도구" }, { en: "at the same time", ko: "동시에" } ] },
  { id: "p5-176", topic: "기술", function: "연결", en: "However, we should be careful about cybersecurity and protect customer data.", ko: "하지만 우리는 사이버 보안에 주의를 기울이고 고객 데이터를 보호해야 한다.", pron: "하우에버 위 슈드 비 케어풀 어바웃 사이버시큐리티 앤 프러텍트 커스터머 데이터", keys: [ { en: "cybersecurity", ko: "사이버 보안" }, { en: "customer data", ko: "고객 데이터(정보)" } ] },
  { id: "p5-177", topic: "기술", function: "결론", en: "To sum up, technology is most helpful when we control how we use it.", ko: "요약하자면, 기술은 우리가 사용 방식을 스스로 조절할 때 가장 도움이 된다.", pron: "투 써멉 테크날러지 이즈 모스트 헬프풀 웬 위 컨트롤 하우 위 유즈 잇", keys: [ { en: "most helpful", ko: "가장 도움이 되는" }, { en: "control how we use it", ko: "사용 방식을 조절하다" } ] },
  { id: "p5-178", topic: "재택근무", function: "의견 시작", en: "I think a hybrid work model is the most practical option for modern offices.", ko: "나는 혼합형 근무 방식이 현대 직장에 가장 실용적인 선택지라고 생각한다.", pron: "아이 띵크 어 하이브리드 웍 모델 이즈 더 모스트 프랙티컬 압션 포 모던 오피시즈", keys: [ { en: "hybrid work model", ko: "혼합형(하이브리드) 근무 방식" }, { en: "practical option", ko: "실용적인 선택지" } ] },
  { id: "p5-179", topic: "재택근무", function: "이유", en: "First of all, employees can focus on individual tasks at home and collaborate at the office.", ko: "무엇보다도 직원들은 집에서 개인 업무에 집중하고 사무실에서는 협업할 수 있다.", pron: "퍼스트 오브 올 엠플로이이즈 캔 포커썬 인디비주얼 태스크스 앳 홈 앤 컬래버레잇 앳 디 오피스", keys: [ { en: "individual tasks", ko: "개인 업무" }, { en: "collaborate", ko: "협업하다" } ] },
  { id: "p5-180", topic: "재택근무", function: "이유", en: "Another reason is that parents can spend more time with their children before and after work.", ko: "또 다른 이유는 부모가 출퇴근 전후에 자녀와 더 많은 시간을 보낼 수 있다는 것이다.", pron: "어나더 리즌 이즈 댓 페어런츠 캔 스펜드 모어 타임 위드 데어 칠드런 비포 앤 애프터 웍", keys: [ { en: "spend more time with", ko: "~와 더 많은 시간을 보내다" }, { en: "before and after work", ko: "출퇴근 전후에" } ] },
  { id: "p5-181", topic: "재택근무", function: "예시", en: "For example, when I work from home on Fridays, I can finish my weekly reports without interruptions.", ko: "예를 들어 금요일에 재택근무를 하면 방해받지 않고 주간 보고서를 끝낼 수 있다.", pron: "포 이그잼플 웬 아이 웍 프럼 홈 온 프라이데이즈 아이 캔 피니쉬 마이 위클리 리포츠 위다웃 인터럽션즈", keys: [ { en: "weekly reports", ko: "주간 보고서" }, { en: "without interruptions", ko: "방해받지 않고" } ] },
  { id: "p5-182", topic: "재택근무", function: "연결", en: "On the other hand, new employees may need more in-person guidance during their first month.", ko: "반면에 신입 직원들은 첫 달 동안 대면 지도가 더 필요할 수도 있다.", pron: "온 디 아더 핸드 뉴 엠플로이이즈 메이 니드 모어 인퍼슨 가이던스 듀링 데어 퍼스트 먼쓰", keys: [ { en: "in-person guidance", ko: "대면 지도" }, { en: "first month", ko: "첫 달" } ] },
  { id: "p5-183", topic: "재택근무", function: "결론", en: "That's why I support combining remote work with regular office days.", ko: "그래서 나는 원격 근무와 정기적인 사무실 출근일을 결합하는 것을 지지한다.", pron: "댓츠 와이 아이 서포트 컴바이닝 리모트 웍 위드 레귤러 오피스 데이즈", keys: [ { en: "combining A with B", ko: "A와 B를 결합하는 것" }, { en: "regular office days", ko: "정기적인 사무실 출근일" } ] },
  { id: "p5-184", topic: "팀워크", function: "의견 시작", en: "I believe respecting different opinions is the most important part of working in a team.", ko: "나는 서로 다른 의견을 존중하는 것이 팀으로 일할 때 가장 중요한 부분이라고 믿는다.", pron: "아이 빌리브 리스펙팅 디퍼런트 오피니언즈 이즈 더 모스트 임포턴트 파러브 워킹 이너 팀", keys: [ { en: "respecting different opinions", ko: "서로 다른 의견을 존중하는 것" }, { en: "working in a team", ko: "팀으로 일하는 것" } ] },
  { id: "p5-185", topic: "팀워크", function: "이유", en: "This is because diverse perspectives help a team find creative solutions to difficult problems.", ko: "이는 다양한 관점이 팀이 어려운 문제에 대한 창의적인 해결책을 찾도록 돕기 때문이다.", pron: "디스 이즈 비코즈 다이버스 퍼스펙티브즈 헬프 어 팀 파인드 크리에이티브 솔루션즈 투 디피컬트 프라블럼즈", keys: [ { en: "diverse perspectives", ko: "다양한 관점" }, { en: "creative solutions", ko: "창의적인 해결책" } ] },
  { id: "p5-186", topic: "팀워크", function: "예시", en: "For instance, when I was in college, my project team combined two ideas and won first prize.", ko: "예를 들어 대학 시절 우리 프로젝트 팀은 두 가지 아이디어를 합쳐서 1등 상을 받았다.", pron: "포 인스턴스 웬 아이 워즈 인 칼리지 마이 프라젝트 팀 컴바인드 투 아이디어즈 앤 원 퍼스트 프라이즈", keys: [ { en: "combined two ideas", ko: "두 아이디어를 합쳤다" }, { en: "won first prize", ko: "1등 상을 받았다" } ] },
  { id: "p5-187", topic: "팀워크", function: "연결", en: "As a result, every team member felt proud of the final outcome.", ko: "그 결과 모든 팀원이 최종 결과물에 자부심을 느꼈다.", pron: "애저 리절트 에브리 팀 멤버 펠트 프라우드 오브 더 파이널 아웃컴", keys: [ { en: "felt proud of", ko: "~에 자부심을 느꼈다" }, { en: "final outcome", ko: "최종 결과물" } ] },
  { id: "p5-188", topic: "팀워크", function: "결론", en: "For these reasons, open communication and mutual respect are essential for any team.", ko: "이러한 이유로 열린 소통과 상호 존중은 어떤 팀에나 필수적이다.", pron: "포 디즈 리즌즈 오픈 커뮤니케이션 앤 뮤추얼 리스펙트 아 이센셜 포 애니 팀", keys: [ { en: "open communication", ko: "열린 의사소통" }, { en: "mutual respect", ko: "상호 존중" } ] },
  { id: "p5-189", topic: "리더십", function: "의견 시작", en: "I think a good leader should encourage team members to share new ideas without fear.", ko: "나는 좋은 리더라면 팀원들이 두려움 없이 새 아이디어를 나누도록 격려해야 한다고 생각한다.", pron: "아이 띵크 어 굿 리더 슈드 인커리지 팀 멤버즈 투 쉐어 뉴 아이디어즈 위다웃 피어", keys: [ { en: "encourage A to", ko: "A가 ~하도록 격려하다" }, { en: "without fear", ko: "두려움 없이" } ] },
  { id: "p5-190", topic: "리더십", function: "이유", en: "First of all, if a manager communicates clearly, team members can understand their priorities quickly.", ko: "무엇보다도 관리자가 명확하게 소통하면 팀원들이 우선순위를 빠르게 이해할 수 있다.", pron: "퍼스트 오브 올 이프 어 매니저 커뮤니케이츠 클리얼리 팀 멤버즈 캔 언더스탠 데어 프라이오러티즈 퀵클리", keys: [ { en: "communicates clearly", ko: "명확하게 소통하다" }, { en: "priorities", ko: "우선순위" } ] },
  { id: "p5-191", topic: "리더십", function: "예시", en: "For example, my first manager always praised our efforts in meetings and gave constructive advice.", ko: "예를 들어 내 첫 상사는 회의에서 항상 우리의 노력을 칭찬하고 건설적인 조언을 해 주었다.", pron: "포 이그잼플 마이 퍼스트 매니저 올웨이즈 프레이즈드 아워 에포츠 인 미팅즈 앤 게이브 컨스트럭티브 어드바이스", keys: [ { en: "praised our efforts", ko: "우리의 노력을 칭찬했다" }, { en: "constructive advice", ko: "건설적인 조언" } ] },
  { id: "p5-192", topic: "리더십", function: "연결", en: "Because of this, our team stayed motivated even when the workload was heavy.", ko: "이 덕분에 업무량이 많을 때에도 우리 팀은 의욕을 잃지 않았다.", pron: "비코저브 디스 아워 팀 스테이드 모티베이티드 이븐 웬 더 워크로드 워즈 헤비", keys: [ { en: "stayed motivated", ko: "의욕을 유지했다" }, { en: "workload", ko: "업무량" } ] },
  { id: "p5-193", topic: "리더십", function: "결론", en: "Therefore, I believe empathy and clear direction make a truly great leader.", ko: "따라서 나는 공감 능력과 명확한 방향 제시가 진정으로 훌륭한 리더를 만든다고 믿는다.", pron: "데어포어 아이 빌리브 엠퍼씨 앤 클리어 디렉션 메익 어 트룰리 그레잇 리더", keys: [ { en: "empathy", ko: "공감 능력" }, { en: "clear direction", ko: "명확한 방향 제시" } ] },
  { id: "p5-194", topic: "환경", function: "의견 시작", en: "I think stores should charge an extra fee for disposable cups to reduce daily waste.", ko: "나는 일상 쓰레기를 줄이기 위해 매장에서 일회용 컵에 추가 요금을 부과해야 한다고 생각한다.", pron: "아이 띵크 스토어즈 슈드 차지 언 엑스트라 피 포 디스포저블 컵스 투 리듀스 데일리 웨이스트", keys: [ { en: "charge an extra fee", ko: "추가 요금을 부과하다" }, { en: "disposable cups", ko: "일회용 컵" } ] },
  { id: "p5-195", topic: "환경", function: "이유", en: "Most importantly, reducing single-use plastic helps protect oceans and wildlife.", ko: "가장 중요한 것은 일회용 플라스틱을 줄이면 바다와 야생 동물을 보호하는 데 도움이 된다는 점이다.", pron: "모스트 임포턴틀리 리듀싱 싱글유스 플래스틱 헬프스 프러텍트 오션즈 앤 와일드라이프", keys: [ { en: "single-use plastic", ko: "일회용 플라스틱" }, { en: "protect oceans", ko: "바다를 보호하다" } ] },
  { id: "p5-196", topic: "환경", function: "이유", en: "Another reason is that eco-friendly habits can also save households money on energy bills.", ko: "또 다른 이유는 친환경 습관이 가정의 에너지 요금을 아껴 줄 수도 있다는 것이다.", pron: "어나더 리즌 이즈 댓 에코프렌들리 해빗츠 캔 올소 세이브 하우스홀즈 머니 온 에너지 빌즈", keys: [ { en: "eco-friendly habits", ko: "친환경 습관" }, { en: "energy bills", ko: "에너지(전기·가스) 요금" } ] },
  { id: "p5-197", topic: "환경", function: "예시", en: "For example, when cafes in my neighborhood offered a discount for tumblers, many customers brought their own cups.", ko: "예를 들어 우리 동네 카페들이 텀블러 할인을 제공했을 때 많은 손님들이 개인 컵을 가져왔다.", pron: "포 이그잼플 웬 캐페이즈 인 마이 네이버후드 오퍼드 어 디스카운트 포 텀블러즈 매니 커스터머즈 브롯 데어 오운 컵스", keys: [ { en: "offered a discount", ko: "할인을 제공했다" }, { en: "brought their own cups", ko: "개인 컵을 가져왔다" } ] },
  { id: "p5-198", topic: "환경", function: "연결", en: "As a result, the amount of trash in our community dropped significantly.", ko: "그 결과 우리 지역 사회의 쓰레기양이 크게 줄어들었다.", pron: "애저 리절트 디 어마운트 오브 트래쉬 인 아워 커뮤니티 드랍트 시그니피컨틀리", keys: [ { en: "the amount of trash", ko: "쓰레기의 양" }, { en: "dropped significantly", ko: "크게 줄어들었다" } ] },
  { id: "p5-199", topic: "환경", function: "결론", en: "That's why I believe small daily actions are the best way to protect the environment.", ko: "그래서 나는 일상의 작은 실천이 환경을 보호하는 가장 좋은 방법이라고 믿는다.", pron: "댓츠 와이 아이 빌리브 스몰 데일리 액션즈 아 더 베스트 웨이 투 프러텍트 디 인바이런먼트", keys: [ { en: "small daily actions", ko: "일상의 작은 실천" }, { en: "protect the environment", ko: "환경을 보호하다" } ] },
  { id: "p5-200", topic: "도시 생활", function: "의견 시작", en: "Personally, I prefer living in a large city with convenient public transportation.", ko: "개인적으로 나는 대중교통이 편리한 대도시에 사는 것을 선호한다.", pron: "퍼스널리 아이 프리퍼 리빙 이너 라지 시티 위드 컨비니언트 퍼블릭 트랜스포테이션", keys: [ { en: "living in a large city", ko: "대도시에 사는 것" }, { en: "convenient public transportation", ko: "편리한 대중교통" } ] },
  { id: "p5-201", topic: "도시 생활", function: "이유", en: "First of all, big cities offer many cultural facilities such as museums, theaters, and libraries.", ko: "무엇보다도 대도시는 박물관, 극장, 도서관 같은 많은 문화 시설을 제공한다.", pron: "퍼스트 오브 올 빅 시티즈 오퍼 매니 컬처럴 퍼실러티즈 써치 애즈 뮤지엄즈 띠어터즈 앤 라이브러리즈", keys: [ { en: "cultural facilities", ko: "문화 시설" }, { en: "museums, theaters, and libraries", ko: "박물관, 극장, 도서관" } ] },
  { id: "p5-202", topic: "도시 생활", function: "예시", en: "For instance, in my city, I can visit a large hospital or a supermarket within ten minutes.", ko: "예를 들어 내가 사는 도시에서는 10분 이내에 대형 병원이나 슈퍼마켓에 갈 수 있다.", pron: "포 인스턴스 인 마이 시티 아이 캔 비짓 어 라지 하스피털 오어 어 수퍼마킷 위딘 텐 미닛츠", keys: [ { en: "large hospital", ko: "대형 병원" }, { en: "within ten minutes", ko: "10분 이내에" } ] },
  { id: "p5-203", topic: "도시 생활", function: "연결", en: "On the other hand, living in a small town is great for people who want peace and quiet.", ko: "반면에 작은 마을에 사는 것은 평화롭고 조용한 환경을 원하는 사람들에게 좋다.", pron: "온 디 아더 핸드 리빙 이너 스몰 타운 이즈 그레잇 포 피플 후 원트 피스 앤 콰이엇", keys: [ { en: "small town", ko: "작은 마을(소도시)" }, { en: "peace and quiet", ko: "평화와 고요함" } ] },
  { id: "p5-204", topic: "도시 생활", function: "결론", en: "All things considered, city life is more suitable for young professionals building their careers.", ko: "모든 것을 고려해 볼 때 도시 생활은 경력을 쌓아 가는 젊은 직장인들에게 더 적합하다.", pron: "올 띵즈 컨시더드 시티 라이프 이즈 모어 수터블 포 영 프로페셔널즈 빌딩 데어 커리어즈", keys: [ { en: "more suitable for", ko: "~에 더 적합한" }, { en: "young professionals", ko: "젊은 직장인(전문직 종사자)들" } ] },
  { id: "p5-205", topic: "온라인 학습", function: "의견 시작", en: "I believe taking online lectures is an effective way to upgrade professional skills.", ko: "나는 온라인 강의를 듣는 것이 직무 역량을 높이는 효과적인 방법이라고 믿는다.", pron: "아이 빌리브 테이킹 온라인 렉쳐즈 이즈 언 이펙티브 웨이 투 업그레이드 프로페셔널 스킬즈", keys: [ { en: "taking online lectures", ko: "온라인 강의를 듣는 것" }, { en: "upgrade professional skills", ko: "직무 역량을 높이다" } ] },
  { id: "p5-206", topic: "온라인 학습", function: "이유", en: "The main reason is that learners can replay difficult lectures as many times as they want.", ko: "주된 이유는 학습자들이 어려운 강의를 원하는 만큼 여러 번 다시 볼 수 있다는 것이다.", pron: "더 메인 리즌 이즈 댓 러너즈 캔 리플레이 디피컬트 렉쳐즈 애즈 매니 타임즈 애즈 데이 원트", keys: [ { en: "replay difficult lectures", ko: "어려운 강의를 다시 재생하다" }, { en: "as many times as they want", ko: "원하는 만큼 여러 번" } ] },
  { id: "p5-207", topic: "온라인 학습", function: "예시", en: "For example, when I prepared for an English test, I watched online lectures on the subway.", ko: "예를 들어 영어 시험을 준비했을 때 나는 지하철에서 온라인 강의를 보았다.", pron: "포 이그잼플 웬 아이 프리페어드 포 언 잉글리쉬 테스트 아이 왓치트 온라인 렉쳐즈 온 더 섭웨이", keys: [ { en: "prepared for an English test", ko: "영어 시험을 준비했다" }, { en: "online lectures", ko: "온라인 강의" } ] },
  { id: "p5-208", topic: "온라인 학습", function: "연결", en: "As a result, I was able to improve my score without quitting my job.", ko: "그 결과 나는 직장을 그만두지 않고도 점수를 올릴 수 있었다.", pron: "애저 리절트 아이 워즈 에이블 투 임프루브 마이 스코어 위다웃 퀴팅 마이 잡", keys: [ { en: "improve my score", ko: "점수를 올리다" }, { en: "without quitting my job", ko: "직장을 그만두지 않고" } ] },
  { id: "p5-209", topic: "온라인 학습", function: "결론", en: "Therefore, I believe online education makes lifelong learning possible for everyone.", ko: "따라서 나는 온라인 교육이 모든 사람에게 평생 학습을 가능하게 해 준다고 믿는다.", pron: "데어포어 아이 빌리브 온라인 에주케이션 메익스 라이프롱 러닝 파서블 포 에브리원", keys: [ { en: "lifelong learning", ko: "평생 학습" }, { en: "possible for everyone", ko: "모든 사람에게 가능한" } ] },
  { id: "p5-210", topic: "소셜 미디어", function: "의견 시작", en: "I think social media helps people stay connected with friends who live far away.", ko: "나는 소셜 미디어가 멀리 사는 친구들과 연락을 유지하는 데 도움이 된다고 생각한다.", pron: "아이 띵크 소셜 미디아 헬프스 피플 스테이 커넥티드 위드 프렌즈 후 리브 파 어웨이", keys: [ { en: "stay connected with", ko: "~와 연락을 유지하다" }, { en: "live far away", ko: "멀리 살다" } ] },
  { id: "p5-211", topic: "소셜 미디어", function: "이유", en: "First of all, small shops can reach many new customers through social media at a low cost.", ko: "무엇보다도 소규모 가게들은 소셜 미디어를 통해 적은 비용으로 많은 신규 고객에게 다가갈 수 있다.", pron: "퍼스트 오브 올 스몰 샵스 캔 리치 매니 뉴 커스터머즈 쓰루 소셜 미디아 앳 어 로우 코스트", keys: [ { en: "reach many new customers", ko: "많은 신규 고객에게 다가가다" }, { en: "at a low cost", ko: "적은 비용으로" } ] },
  { id: "p5-212", topic: "소셜 미디어", function: "이유", en: "Another reason is that people can share useful daily tips and news right away.", ko: "또 다른 이유는 사람들이 유용한 생활 정보와 뉴스를 즉시 공유할 수 있다는 것이다.", pron: "어나더 리즌 이즈 댓 피플 캔 쉐어 유스풀 데일리 팁스 앤 뉴즈 라잇 어웨이", keys: [ { en: "useful daily tips", ko: "유용한 생활 정보" }, { en: "right away", ko: "즉시, 바로" } ] },
  { id: "p5-213", topic: "소셜 미디어", function: "예시", en: "For example, my friend opened a small bakery and attracted many visitors by posting photos online.", ko: "예를 들어 내 친구는 작은 빵집을 열었는데 온라인에 사진을 올려 많은 방문객을 모았다.", pron: "포 이그잼플 마이 프렌드 오픈드 어 스몰 베이커리 앤 어트랙티드 매니 비지터즈 바이 포스팅 포토즈 온라인", keys: [ { en: "attracted many visitors", ko: "많은 방문객을 모았다" }, { en: "by posting photos", ko: "사진을 올림으로써" } ] },
  { id: "p5-214", topic: "소셜 미디어", function: "연결", en: "However, we should always check whether online information is true before sharing it.", ko: "하지만 온라인 정보를 공유하기 전에 그것이 사실인지 항상 확인해야 한다.", pron: "하우에버 위 슈드 올웨이즈 첵 웨더 온라인 인포메이션 이즈 트루 비포 쉐어링 잇", keys: [ { en: "check whether", ko: "~인지 확인하다" }, { en: "before sharing it", ko: "공유하기 전에" } ] },
  { id: "p5-215", topic: "소셜 미디어", function: "결론", en: "That's why I believe social media is very beneficial when we use it responsibly.", ko: "그래서 나는 소셜 미디어를 책임감 있게 사용할 때 매우 이롭다고 믿는다.", pron: "댓츠 와이 아이 빌리브 소셜 미디아 이즈 베리 베너피셜 웬 위 유즈 잇 리스판서블리", keys: [ { en: "beneficial", ko: "이로운, 유익한" }, { en: "use it responsibly", ko: "책임감 있게 사용하다" } ] },
  { id: "p5-216", topic: "진로", function: "의견 시작", en: "In my opinion, doing an internship in college is the best way to prepare for a career.", ko: "내 생각에는 대학 시절 인턴십을 하는 것이 진로를 준비하는 가장 좋은 방법이다.", pron: "인 마이 오피니언 두잉 언 인턴쉽 인 칼리지 이즈 더 베스트 웨이 투 프리페어 포 어 커리어", keys: [ { en: "doing an internship", ko: "인턴십을 하는 것" }, { en: "prepare for a career", ko: "진로(취업)를 준비하다" } ] },
  { id: "p5-217", topic: "진로", function: "이유", en: "The main reason is that students can find out what kind of work truly suits them.", ko: "주된 이유는 학생들이 어떤 종류의 일이 자신에게 진정으로 맞는지 알아낼 수 있다는 것이다.", pron: "더 메인 리즌 이즈 댓 스튜던츠 캔 파인다웃 왓 카인더브 웍 트룰리 수츠 뎀", keys: [ { en: "find out", ko: "알아내다" }, { en: "truly suits them", ko: "그들에게 진정으로 맞다" } ] },
  { id: "p5-218", topic: "진로", function: "이유", en: "Secondly, a clear career goal helps young people choose the right training courses.", ko: "둘째로, 명확한 진로 목표는 젊은이들이 알맞은 교육 과정을 선택하는 데 도움이 된다.", pron: "세컨들리 어 클리어 커리어 고울 헬프스 영 피플 츄즈 더 라잇 트레이닝 코어시즈", keys: [ { en: "clear career goal", ko: "명확한 진로 목표" }, { en: "the right training courses", ko: "알맞은 교육 과정" } ] },
  { id: "p5-219", topic: "진로", function: "예시", en: "In my case, when I was a senior in college, a short internship helped me choose my current job.", ko: "내 경우에는 대학교 4학년 때 했던 짧은 인턴십이 지금의 직업을 고르는 데 도움이 되었다.", pron: "인 마이 케이스 웬 아이 워즈 어 시니어 인 칼리지 어 숏 인턴쉽 헬프트 미 츄즈 마이 커런트 잡", keys: [ { en: "a senior in college", ko: "대학교 4학년" }, { en: "current job", ko: "현재 직업" } ] },
  { id: "p5-220", topic: "진로", function: "연결", en: "As a result, I felt much more confident when I had my job interview.", ko: "그 결과 나는 취업 면접을 볼 때 훨씬 더 자신감을 느꼈다.", pron: "애저 리절트 아이 펠트 머치 모어 칸피던트 웬 아이 해드 마이 잡 인터뷰", keys: [ { en: "much more confident", ko: "훨씬 더 자신감 있는" }, { en: "job interview", ko: "취업 면접" } ] },
  { id: "p5-221", topic: "진로", function: "결론", en: "Therefore, I think real workplace experience is invaluable for students before graduation.", ko: "따라서 나는 졸업 전 학생들에게 실제 직장 경험이 매우 귀중하다고 생각한다.", pron: "데어포어 아이 띵크 리얼 웍플레이스 익스피리언스 이즈 인밸류어블 포 스튜던츠 비포 그래쥬에이션", keys: [ { en: "real workplace experience", ko: "실제 직장 경험" }, { en: "invaluable", ko: "매우 귀중한" } ] },
  { id: "p5-222", topic: "경영", function: "의견 시작", en: "I believe companies should support employees who want to learn new digital skills.", ko: "나는 회사가 새로운 디지털 기술을 배우고 싶어 하는 직원들을 지원해야 한다고 믿는다.", pron: "아이 빌리브 컴퍼니즈 슈드 서포트 엠플로이이즈 후 원트 투 런 뉴 디지털 스킬즈", keys: [ { en: "support employees", ko: "직원들을 지원하다" }, { en: "digital skills", ko: "디지털 기술" } ] },
  { id: "p5-223", topic: "경영", function: "이유", en: "First of all, well-trained employees can handle new tasks much faster and more accurately.", ko: "무엇보다도 잘 교육받은 직원들은 새로운 업무를 훨씬 더 빠르고 정확하게 처리할 수 있다.", pron: "퍼스트 오브 올 웰트레인드 엠플로이이즈 캔 핸들 뉴 태스크스 머치 패스터 앤 모어 애큐럿리", keys: [ { en: "well-trained employees", ko: "잘 교육받은 직원들" }, { en: "more accurately", ko: "더 정확하게" } ] },
  { id: "p5-224", topic: "경영", function: "이유", en: "Another reason is that recognizing hard work builds strong loyalty within the company.", ko: "또 다른 이유는 성실한 노력을 인정해 주는 것이 회사 안에서 강한 애사심을 키워 준다는 것이다.", pron: "어나더 리즌 이즈 댓 레커그나이징 하드 웍 빌즈 스트롱 로열티 위딘 더 컴퍼니", keys: [ { en: "recognizing hard work", ko: "성실한 노력을 인정하는 것" }, { en: "strong loyalty", ko: "강한 충성심(애사심)" } ] },
  { id: "p5-225", topic: "경영", function: "예시", en: "For example, my company offered a data analysis course last year, and our team saved hours every week.", ko: "예를 들어 우리 회사는 작년에 데이터 분석 강좌를 제공했고 우리 팀은 매주 몇 시간을 절약했다.", pron: "포 이그잼플 마이 컴퍼니 오퍼드 어 데이터 어낼러시스 코어스 래스트 이어 앤 아워 팀 세이브드 아워즈 에브리 윅", keys: [ { en: "data analysis course", ko: "데이터 분석 강좌" }, { en: "saved hours", ko: "몇 시간을 절약했다" } ] },
  { id: "p5-226", topic: "경영", function: "연결", en: "Because of this, our department achieved its annual sales target two months early.", ko: "이 덕분에 우리 부서는 연간 매출 목표를 두 달 일찍 달성했다.", pron: "비코저브 디스 아워 디파트먼트 어치브드 잇츠 애뉴얼 세일즈 타깃 투 먼쓰 얼리", keys: [ { en: "annual sales target", ko: "연간 매출 목표" }, { en: "two months early", ko: "두 달 일찍" } ] },
  { id: "p5-227", topic: "경영", function: "결론", en: "For these reasons, I believe supporting employee development is the smartest investment for any business.", ko: "이러한 이유로 나는 직원 역량 개발을 지원하는 것이 어떤 기업에나 가장 현명한 투자라고 믿는다.", pron: "포 디즈 리즌즈 아이 빌리브 서포팅 엠플로이 디벨롭먼트 이즈 더 스마티스트 인베스트먼트 포 애니 비즈니스", keys: [ { en: "employee development", ko: "직원 역량 개발" }, { en: "smartest investment", ko: "가장 현명한 투자" } ] },
  { id: "p5-228", topic: "고객 서비스", function: "의견 시작", en: "I believe listening politely to customers is the most important skill in customer service.", ko: "나는 고객의 말을 정중하게 경청하는 것이 고객 서비스에서 가장 중요한 기술이라고 믿는다.", pron: "아이 빌리브 리쓰닝 폴라이틀리 투 커스터머즈 이즈 더 모스트 임포턴트 스킬 인 커스터머 서비스", keys: [ { en: "listening politely", ko: "정중하게 경청하는 것" }, { en: "customer service", ko: "고객 서비스" } ] },
  { id: "p5-229", topic: "고객 서비스", function: "이유", en: "This is because customers feel valued when a staff member understands their problem quickly.", ko: "이는 직원이 자신의 문제를 빠르게 이해해 줄 때 고객이 존중받는다고 느끼기 때문이다.", pron: "디스 이즈 비코즈 커스터머즈 필 밸류드 웬 어 스태프 멤버 언더스탠즈 데어 프라블럼 퀵클리", keys: [ { en: "feel valued", ko: "존중받는다고(소중히 여겨진다고) 느끼다" }, { en: "staff member", ko: "직원" } ] },
  { id: "p5-230", topic: "고객 서비스", function: "이유", en: "One of the biggest advantages of good service is that satisfied customers recommend the store to their friends.", ko: "좋은 서비스의 가장 큰 장점 중 하나는 만족한 고객이 친구들에게 그 매장을 추천한다는 것이다.", pron: "워너브 더 비기스트 어드밴티지즈 오브 굿 서비스 이즈 댓 새티스파이드 커스터머즈 레커멘드 더 스토어 투 데어 프렌즈", keys: [ { en: "satisfied customers", ko: "만족한 고객들" }, { en: "recommend A to B", ko: "B에게 A를 추천하다" } ] },
  { id: "p5-231", topic: "고객 서비스", function: "예시", en: "For instance, when I bought a defective lamp, the store replaced it right away with a kind apology.", ko: "예를 들어 내가 결함이 있는 스탠드를 샀을 때 매장에서 친절한 사과와 함께 즉시 교환해 주었다.", pron: "포 인스턴스 웬 아이 봇 어 디펙티브 램프 더 스토어 리플레이스트 잇 라잇 어웨이 위드 어 카인드 어팔러지", keys: [ { en: "defective", ko: "결함이 있는" }, { en: "replaced it right away", ko: "즉시 교환해 주었다" } ] },
  { id: "p5-232", topic: "고객 서비스", function: "연결", en: "As a result, I trusted that brand even more and continued to shop there.", ko: "그 결과 나는 그 브랜드를 더욱 신뢰하게 되었고 그곳에서 계속 쇼핑했다.", pron: "애저 리절트 아이 트러스티드 댓 브랜드 이븐 모어 앤 컨티뉴드 투 샵 데어", keys: [ { en: "trusted that brand", ko: "그 브랜드를 신뢰했다" }, { en: "continued to", ko: "계속 ~했다" } ] },
  { id: "p5-233", topic: "고객 서비스", function: "결론", en: "To sum up, friendly and fast service is the key to building long-term customer trust.", ko: "요약하자면, 친절하고 빠른 서비스가 장기적인 고객 신뢰를 쌓는 열쇠이다.", pron: "투 써멉 프렌들리 앤 패스트 서비스 이즈 더 키 투 빌딩 롱텀 커스터머 트러스트", keys: [ { en: "the key to", ko: "~의 열쇠, 비결" }, { en: "long-term customer trust", ko: "장기적인 고객 신뢰" } ] },
  { id: "p5-234", topic: "조언", function: "의견 시작", en: "I prefer talking to my parents or close friends when I need advice about an important decision.", ko: "중요한 결정에 대해 조언이 필요할 때 나는 부모님이나 친한 친구들과 이야기하는 것을 선호한다.", pron: "아이 프리퍼 토킹 투 마이 페어런츠 오어 클로스 프렌즈 웬 아이 니드 어드바이스 어바웃 언 임포턴트 디시전", keys: [ { en: "need advice", ko: "조언이 필요하다" }, { en: "close friends", ko: "친한 친구들" } ] },
  { id: "p5-235", topic: "조언", function: "이유", en: "First of all, they know my personality and strengths better than anyone else.", ko: "무엇보다도 그들은 누구보다 내 성격과 강점을 더 잘 알고 있다.", pron: "퍼스트 오브 올 데이 노우 마이 퍼스낼러티 앤 스트렝쓰스 베러 댄 애니원 엘스", keys: [ { en: "personality and strengths", ko: "성격과 강점" }, { en: "better than anyone else", ko: "누구보다 더 잘" } ] },
  { id: "p5-236", topic: "조언", function: "이유", en: "Another reason is that they truly care about my happiness and give honest feedback.", ko: "또 다른 이유는 그들이 내 행복을 진심으로 아끼고 솔직한 조언을 해 준다는 것이다.", pron: "어나더 리즌 이즈 댓 데이 트룰리 케어 어바웃 마이 해피니스 앤 기브 아너스트 피드백", keys: [ { en: "care about", ko: "~을 아끼다, 신경 쓰다" }, { en: "honest feedback", ko: "솔직한 피드백(조언)" } ] },
  { id: "p5-237", topic: "조언", function: "예시", en: "For example, when I worried about changing my job, my older sister gave me warm encouragement.", ko: "예를 들어 내가 이직을 고민했을 때 언니(누나)가 따뜻한 격려를 해 주었다.", pron: "포 이그잼플 웬 아이 워리드 어바웃 체인징 마이 잡 마이 올더 시스터 게이브 미 웜 인커리지먼트", keys: [ { en: "worried about", ko: "~에 대해 걱정했다(고민했다)" }, { en: "warm encouragement", ko: "따뜻한 격려" } ] },
  { id: "p5-238", topic: "조언", function: "연결", en: "Because of this, I was able to make my decision calmly without regret.", ko: "이 덕분에 나는 후회 없이 차분하게 결정을 내릴 수 있었다.", pron: "비코저브 디스 아이 워즈 에이블 투 메익 마이 디시전 캄리 위다웃 리그렛", keys: [ { en: "make my decision", ko: "결정을 내리다" }, { en: "without regret", ko: "후회 없이" } ] },
  { id: "p5-239", topic: "조언", function: "결론", en: "That's why I always turn to people I trust when I face a big choice.", ko: "그래서 나는 큰 선택에 직면할 때 언제나 내가 믿는 사람들에게 조언을 구한다.", pron: "댓츠 와이 아이 올웨이즈 턴 투 피플 아이 트러스트 웬 아이 페이스 어 빅 쵸이스", keys: [ { en: "turn to", ko: "~에게 의지하다, 도움을 청하다" }, { en: "face a big choice", ko: "큰 선택에 직면하다" } ] },
  { id: "p5-240", topic: "스트레스", function: "의견 시작", en: "I think having a regular hobby after work is the best way to manage daily stress.", ko: "나는 퇴근 후 규칙적인 취미 생활을 하는 것이 일상의 스트레스를 관리하는 가장 좋은 방법이라고 생각한다.", pron: "아이 띵크 해빙 어 레귤러 하비 애프터 웍 이즈 더 베스트 웨이 투 매니지 데일리 스트레스", keys: [ { en: "regular hobby", ko: "규칙적인 취미" }, { en: "manage daily stress", ko: "일상의 스트레스를 관리하다" } ] },
  { id: "p5-241", topic: "스트레스", function: "이유", en: "The main reason is that doing something enjoyable helps people forget about work worries.", ko: "주된 이유는 즐거운 일을 하는 것이 사람들이 업무 걱정을 잊도록 도와준다는 것이다.", pron: "더 메인 리즌 이즈 댓 두잉 썸띵 인조이어블 헬프스 피플 퍼겟 어바웃 웍 워리즈", keys: [ { en: "something enjoyable", ko: "즐거운 일" }, { en: "forget about", ko: "~을 잊다" } ] },
  { id: "p5-242", topic: "스트레스", function: "이유", en: "Secondly, outdoor activities like running or hiking refresh both the body and the mind.", ko: "둘째로, 달리기나 등산 같은 야외 활동은 몸과 마음을 모두 상쾌하게 해 준다.", pron: "세컨들리 아웃도어 액티비티즈 라익 러닝 오어 하이킹 리프레쉬 보쓰 더 바디 앤 더 마인드", keys: [ { en: "outdoor activities", ko: "야외 활동" }, { en: "both the body and the mind", ko: "몸과 마음 모두" } ] },
  { id: "p5-243", topic: "스트레스", function: "예시", en: "In my case, when I started swimming twice a week, I slept much better at night.", ko: "내 경우에는 일주일에 두 번 수영을 시작했을 때 밤에 훨씬 더 잘 잤다.", pron: "인 마이 케이스 웬 아이 스타티드 스위밍 트와이스 어 윅 아이 슬렙트 머치 베러 앳 나잇", keys: [ { en: "twice a week", ko: "일주일에 두 번" }, { en: "slept much better", ko: "훨씬 더 잘 잤다" } ] },
  { id: "p5-244", topic: "스트레스", function: "연결", en: "As a result, I had more energy in the morning and worked more efficiently.", ko: "그 결과 아침에 에너지가 더 생겼고 더 효율적으로 일했다.", pron: "애저 리절트 아이 해드 모어 에너지 인 더 모닝 앤 웍트 모어 이피션틀리", keys: [ { en: "more energy", ko: "더 많은 에너지" }, { en: "worked more efficiently", ko: "더 효율적으로 일했다" } ] },
  { id: "p5-245", topic: "스트레스", function: "결론", en: "Therefore, I believe taking time to recharge is essential for a healthy life.", ko: "따라서 나는 재충전할 시간을 갖는 것이 건강한 삶에 필수적이라고 믿는다.", pron: "데어포어 아이 빌리브 테이킹 타임 투 리차쥐 이즈 이센셜 포 어 헬씨 라이프", keys: [ { en: "taking time to recharge", ko: "재충전할 시간을 갖는 것" }, { en: "healthy life", ko: "건강한 삶" } ] },
  { id: "p5-246", topic: "가치관", function: "의견 시작", en: "Personally, I prefer spending money on meaningful experiences rather than buying expensive goods.", ko: "개인적으로 나는 비싼 물건을 사는 것보다 의미 있는 경험에 돈을 쓰는 것을 선호한다.", pron: "퍼스널리 아이 프리퍼 스펜딩 머니 온 미닝풀 익스피리언시즈 래더 댄 바잉 익스펜시브 굿즈", keys: [ { en: "spending money on", ko: "~에 돈을 쓰다" }, { en: "meaningful experiences", ko: "의미 있는 경험" } ] },
  { id: "p5-247", topic: "가치관", function: "이유", en: "First of all, a new item gets old quickly, but good memories stay with us for a lifetime.", ko: "무엇보다도 새 물건은 금방 낡지만 좋은 추억은 평생 우리 곁에 남는다.", pron: "퍼스트 오브 올 어 뉴 아이템 겟츠 올드 퀵클리 벗 굿 메모리즈 스테이 위드 어스 포 어 라이프타임", keys: [ { en: "good memories", ko: "좋은 추억" }, { en: "for a lifetime", ko: "평생 동안" } ] },
  { id: "p5-248", topic: "가치관", function: "이유", en: "Another reason is that traveling or taking classes helps us grow as a person.", ko: "또 다른 이유는 여행을 하거나 수업을 듣는 것이 우리가 한 사람으로서 성장하도록 돕는다는 것이다.", pron: "어나더 리즌 이즈 댓 트래블링 오어 테이킹 클래시즈 헬프스 어스 그로우 애즈 어 퍼슨", keys: [ { en: "taking classes", ko: "수업을 듣는 것" }, { en: "grow as a person", ko: "한 사람으로서 성장하다" } ] },
  { id: "p5-249", topic: "가치관", function: "예시", en: "For example, when I traveled to Jeju Island with my parents, we made unforgettable memories together.", ko: "예를 들어 부모님과 제주도로 여행을 갔을 때 우리는 함께 잊지 못할 추억을 만들었다.", pron: "포 이그잼플 웬 아이 트래블드 투 제주 아일랜드 위드 마이 페어런츠 위 메이드 언포게터블 메모리즈 투게더", keys: [ { en: "traveled to", ko: "~로 여행을 갔다" }, { en: "unforgettable memories", ko: "잊지 못할 추억" } ] },
  { id: "p5-250", topic: "가치관", function: "연결", en: "Of course, saving money for the future is important, but we should also enjoy the present.", ko: "물론 미래를 위해 저축하는 것도 중요하지만 현재를 즐기는 것 또한 중요하다.", pron: "어브 코어스 세이빙 머니 포 더 퓨쳐 이즈 임포턴트 벗 위 슈드 올소 인조이 더 프레즌트", keys: [ { en: "saving money", ko: "돈을 저축하는 것" }, { en: "enjoy the present", ko: "현재를 즐기다" } ] },
  { id: "p5-251", topic: "가치관", function: "결론", en: "That's why I think experiences bring much greater happiness than material possessions.", ko: "그래서 나는 물질적 소유물보다 경험이 훨씬 더 큰 행복을 준다고 생각한다.", pron: "댓츠 와이 아이 띵크 익스피리언시즈 브링 머치 그레이터 해피니스 댄 머티리얼 퍼제션즈", keys: [ { en: "greater happiness", ko: "더 큰 행복" }, { en: "material possessions", ko: "물질적 소유물" } ] },
  { id: "p5-252", topic: "성공", function: "의견 시작", en: "I believe consistent effort is more important than natural talent for achieving success.", ko: "나는 성공을 이루는 데 타고난 재능보다 꾸준한 노력이 더 중요하다고 믿는다.", pron: "아이 빌리브 컨시스턴트 에포트 이즈 모어 임포턴트 댄 내추럴 탤런트 포 어치빙 석세스", keys: [ { en: "consistent effort", ko: "꾸준한 노력" }, { en: "natural talent", ko: "타고난 재능" } ] },
  { id: "p5-253", topic: "성공", function: "이유", en: "The main reason is that anyone can improve their skills if they practice steadily every day.", ko: "주된 이유는 매일 꾸준히 연습하면 누구나 자신의 실력을 향상시킬 수 있다는 것이다.", pron: "더 메인 리즌 이즈 댓 애니원 캔 임프루브 데어 스킬즈 이프 데이 프랙티스 스테딜리 에브리 데이", keys: [ { en: "improve their skills", ko: "실력을 향상시키다" }, { en: "practice steadily", ko: "꾸준히 연습하다" } ] },
  { id: "p5-254", topic: "성공", function: "이유", en: "Most importantly, people who do not give up easily can overcome unexpected difficulties.", ko: "가장 중요한 것은 쉽게 포기하지 않는 사람들이 예상치 못한 어려움을 극복할 수 있다는 점이다.", pron: "모스트 임포턴틀리 피플 후 두 낫 기브 업 이즐리 캔 오버컴 언익스펙티드 디피컬티즈", keys: [ { en: "give up easily", ko: "쉽게 포기하다" }, { en: "overcome", ko: "극복하다" } ] },
  { id: "p5-255", topic: "성공", function: "예시", en: "For instance, when I first started giving presentations in English, I practiced for thirty minutes every night.", ko: "예를 들어 내가 처음 영어로 발표를 시작했을 때 나는 매일 밤 30분씩 연습했다.", pron: "포 인스턴스 웬 아이 퍼스트 스타티드 기빙 프레젠테이션즈 인 잉글리쉬 아이 프랙티스트 포 써티 미닛츠 에브리 나잇", keys: [ { en: "giving presentations", ko: "발표하는 것" }, { en: "every night", ko: "매일 밤" } ] },
  { id: "p5-256", topic: "성공", function: "연결", en: "As a result, I became much more fluent and received positive feedback from my clients.", ko: "그 결과 나는 훨씬 더 유창해졌고 고객들로부터 긍정적인 평가를 받았다.", pron: "애저 리절트 아이 비케임 머치 모어 플루언트 앤 리시브드 파지티브 피드백 프럼 마이 클라이언츠", keys: [ { en: "much more fluent", ko: "훨씬 더 유창한" }, { en: "positive feedback", ko: "긍정적인 피드백(평가)" } ] },
  { id: "p5-257", topic: "성공", function: "결론", en: "In conclusion, patience and daily practice are the true keys to long-term success.", ko: "결론적으로 인내심과 매일의 연습이 장기적인 성공의 진정한 비결이다.", pron: "인 컨클루전 페이션스 앤 데일리 프랙티스 아 더 트루 키즈 투 롱텀 석세스", keys: [ { en: "patience", ko: "인내심" }, { en: "long-term success", ko: "장기적인 성공" } ] },
  { id: "p5-258", topic: "인공지능", function: "의견 시작", en: "I think learning how to use artificial intelligence tools is essential for modern workers.", ko: "나는 현대 직장인들에게 인공지능 도구를 활용하는 법을 배우는 것이 필수적이라고 생각한다.", pron: "아이 띵크 러닝 하우 투 유즈 아티피셜 인텔리전스 툴즈 이즈 이센셜 포 모던 워커즈", keys: [ { en: "how to use", ko: "사용하는 방법" }, { en: "modern workers", ko: "현대 직장인들" } ] },
  { id: "p5-259", topic: "인공지능", function: "이유", en: "First of all, it can automate repetitive work and save several hours every week.", ko: "무엇보다도 그것은 반복적인 업무를 자동화하고 매주 몇 시간을 아껴 줄 수 있다.", pron: "퍼스트 오브 올 잇 캔 오토메잇 리페터티브 웍 앤 세이브 세버럴 아워즈 에브리 윅", keys: [ { en: "repetitive work", ko: "반복적인 업무" }, { en: "save several hours", ko: "몇 시간을 아끼다" } ] },
  { id: "p5-260", topic: "인공지능", function: "이유", en: "Another reason is that workers can spend more time on creative planning and problem solving.", ko: "또 다른 이유는 근로자들이 창의적인 기획과 문제 해결에 더 많은 시간을 쓸 수 있다는 것이다.", pron: "어나더 리즌 이즈 댓 워커즈 캔 스펜드 모어 타임 온 크리에이티브 플래닝 앤 프라블럼 솔빙", keys: [ { en: "creative planning", ko: "창의적인 기획" }, { en: "problem solving", ko: "문제 해결" } ] },
  { id: "p5-261", topic: "인공지능", function: "예시", en: "For example, when I used an AI tool to organize survey data, I finished the report in half the time.", ko: "예를 들어 설문 데이터를 정리할 때 인공지능 도구를 사용했더니 절반의 시간 만에 보고서를 끝냈다.", pron: "포 이그잼플 웬 아이 유즈드 언 에이아이 툴 투 오거나이즈 서베이 데이터 아이 피니쉬트 더 리포트 인 해프 더 타임", keys: [ { en: "organize survey data", ko: "설문 데이터를 정리하다" }, { en: "in half the time", ko: "절반의 시간 만에" } ] },
  { id: "p5-262", topic: "인공지능", function: "연결", en: "However, people should always double-check the results because AI can sometimes make mistakes.", ko: "하지만 인공지능이 때때로 실수를 할 수 있기 때문에 사람들은 결과를 항상 재확인해야 한다.", pron: "하우에버 피플 슈드 올웨이즈 더블첵 더 리절츠 비코즈 에이아이 캔 썸타임즈 메익 미스테익스", keys: [ { en: "double-check", ko: "재확인하다, 꼼꼼히 확인하다" }, { en: "make mistakes", ko: "실수를 하다" } ] },
  { id: "p5-263", topic: "인공지능", function: "결론", en: "Therefore, I believe combining human judgment with AI technology brings the best results.", ko: "따라서 나는 인간의 판단력과 인공지능 기술을 결합하는 것이 최상의 결과를 가져온다고 믿는다.", pron: "데어포어 아이 빌리브 컴바이닝 휴먼 저지먼트 위드 에이아이 테크날러지 브링즈 더 베스트 리절츠", keys: [ { en: "human judgment", ko: "인간의 판단력" }, { en: "the best results", ko: "최상의 결과" } ] },
  { id: "p5-264", topic: "워라밸", function: "의견 시작", en: "I believe companies should discourage sending work messages after office hours.", ko: "나는 회사가 퇴근 시간 이후에 업무 메시지를 보내는 것을 자제시켜야 한다고 믿는다.", pron: "아이 빌리브 컴퍼니즈 슈드 디스커리지 센딩 웍 메시지즈 애프터 오피스 아워즈", keys: [ { en: "discourage", ko: "자제시키다, 막다" }, { en: "after office hours", ko: "업무(퇴근) 시간 이후에" } ] },
  { id: "p5-265", topic: "워라밸", function: "이유", en: "The main reason is that employees need enough rest in the evening to prevent burnout.", ko: "주된 이유는 직원들이 번아웃을 예방하기 위해 저녁에 충분한 휴식이 필요하다는 것이다.", pron: "더 메인 리즌 이즈 댓 엠플로이이즈 니드 이너프 레스트 인 디 이브닝 투 프리벤트 번아웃", keys: [ { en: "enough rest", ko: "충분한 휴식" }, { en: "prevent burnout", ko: "번아웃(소진)을 예방하다" } ] },
  { id: "p5-266", topic: "워라밸", function: "이유", en: "Secondly, employees are more focused during work hours when they enjoy a healthy work-life balance.", ko: "둘째로, 직원들은 건강한 워라밸을 누릴 때 근무 시간 동안 더 집중한다.", pron: "세컨들리 엠플로이이즈 아 모어 포커스트 듀링 웍 아워즈 웬 데이 인조이 어 헬씨 웍라이프 밸런스", keys: [ { en: "healthy work-life balance", ko: "건강한 일과 삶의 균형" }, { en: "during work hours", ko: "근무 시간 동안" } ] },
  { id: "p5-267", topic: "워라밸", function: "예시", en: "For instance, my company encourages everyone to use all of their annual vacation days.", ko: "예를 들어 우리 회사는 모든 직원이 연차 휴가를 전부 사용하도록 장려한다.", pron: "포 인스턴스 마이 컴퍼니 인커리지즈 에브리원 투 유즈 올 오브 데어 애뉴얼 베이케이션 데이즈", keys: [ { en: "encourage A to", ko: "A가 ~하도록 장려하다" }, { en: "annual vacation days", ko: "연차 휴가" } ] },
  { id: "p5-268", topic: "워라밸", function: "연결", en: "As a result, our team members return from vacation feeling refreshed and motivated.", ko: "그 결과 우리 팀원들은 상쾌하고 의욕이 넘치는 상태로 휴가에서 돌아온다.", pron: "애저 리절트 아워 팀 멤버즈 리턴 프럼 베이케이션 필링 리프레쉬트 앤 모티베이티드", keys: [ { en: "return from vacation", ko: "휴가에서 돌아오다" }, { en: "refreshed and motivated", ko: "상쾌하고 의욕이 넘치는" } ] },
  { id: "p5-269", topic: "워라밸", function: "결론", en: "That's why respecting employees' personal time is beneficial for both workers and companies.", ko: "그래서 직원의 개인 시간을 존중하는 것이 근로자와 회사 모두에게 이롭다.", pron: "댓츠 와이 리스펙팅 엠플로이이즈 퍼스널 타임 이즈 베너피셜 포 보쓰 워커즈 앤 컴퍼니즈", keys: [ { en: "personal time", ko: "개인 시간" }, { en: "beneficial for both", ko: "양쪽 모두에게 이로운" } ] },
  { id: "p5-270", topic: "소비", function: "의견 시작", en: "In my view, it is better to buy a few high-quality items than many cheap ones.", ko: "내 견해로는 값싼 물건을 여러 개 사는 것보다 품질 좋은 물건을 몇 개 사는 것이 더 낫다.", pron: "인 마이 뷰 잇 이즈 베러 투 바이 어 퓨 하이 퀄러티 아이템즈 댄 매니 칩 원즈", keys: [ { en: "high-quality items", ko: "품질 좋은 물건들" }, { en: "cheap ones", ko: "값싼 것들" } ] },
  { id: "p5-271", topic: "소비", function: "이유", en: "First of all, a durable product can last much longer, so we can actually save money over time.", ko: "무엇보다도 튼튼한 제품은 훨씬 오래 쓸 수 있어서 시간이 지나면 실제로 돈을 아낄 수 있다.", pron: "퍼스트 오브 올 어 듀러블 프라덕트 캔 래스트 머치 롱거 쏘 위 캔 액추얼리 세이브 머니 오버 타임", keys: [ { en: "durable product", ko: "튼튼한(내구성 있는) 제품" }, { en: "over time", ko: "시간이 지나면서, 장기적으로" } ] },
  { id: "p5-272", topic: "소비", function: "예시", en: "For example, I bought a good winter coat five years ago, and it still looks like new today.", ko: "예를 들어 나는 5년 전에 좋은 겨울 코트를 샀는데, 오늘날에도 여전히 새것처럼 보인다.", pron: "포 이그잼플 아이 봇 어 굿 윈터 코트 파이브 이어즈 어고우 앤 잇 스틸 룩스 라익 뉴 투데이", keys: [ { en: "winter coat", ko: "겨울 코트" }, { en: "looks like new", ko: "새것처럼 보인다" } ] },
  { id: "p5-273", topic: "소비", function: "연결", en: "Because of this, I no longer waste money replacing cheap clothes every year.", ko: "이 덕분에 나는 더 이상 매년 값싼 옷을 교체하느라 돈을 낭비하지 않는다.", pron: "비코저브 디스 아이 노 롱거 웨이스트 머니 리플레이싱 칩 클로우즈 에브리 이어", keys: [ { en: "waste money", ko: "돈을 낭비하다" }, { en: "every year", ko: "매년" } ] },
  { id: "p5-274", topic: "소비", function: "결론", en: "To sum up, smart spending means choosing quality and value over low prices.", ko: "요약하자면 현명한 소비란 낮은 가격보다 품질과 가치를 선택하는 것을 뜻한다.", pron: "투 써멉 스마트 스펜딩 민즈 츄징 퀄러티 앤 밸류 오버 로우 프라이시즈", keys: [ { en: "smart spending", ko: "현명한 소비" }, { en: "quality and value", ko: "품질과 가치" } ] },
  { id: "p5-275", topic: "건강", function: "의견 시작", en: "I think companies should support employees' health by offering gym memberships or healthy meals.", ko: "나는 회사가 헬스장 회원권이나 건강한 식사를 제공하여 직원들의 건강을 지원해야 한다고 생각한다.", pron: "아이 띵크 컴퍼니즈 슈드 서포트 엠플로이이즈 헬쓰 바이 오퍼링 짐 멤버쉽스 오어 헬씨 밀즈", keys: [ { en: "gym memberships", ko: "헬스장 회원권" }, { en: "healthy meals", ko: "건강한 식사" } ] },
  { id: "p5-276", topic: "건강", function: "이유", en: "This is because healthy employees have more energy and take fewer sick days.", ko: "이는 건강한 직원이 에너지가 더 넘치고 병가를 덜 내기 때문이다.", pron: "디스 이즈 비코즈 헬씨 엠플로이이즈 해브 모어 에너지 앤 테익 퓨어 식 데이즈", keys: [ { en: "healthy employees", ko: "건강한 직원들" }, { en: "sick days", ko: "병가" } ] },
  { id: "p5-277", topic: "건강", function: "예시", en: "For example, when my company started providing fresh salads at the cafeteria, many workers ate healthier lunches.", ko: "예를 들어 우리 회사가 구내식당에서 신선한 샐러드를 제공하기 시작했을 때 많은 직원들이 더 건강한 점심을 먹었다.", pron: "포 이그잼플 웬 마이 컴퍼니 스타티드 프러바이딩 프레쉬 샐러즈 앳 더 캐퍼테리아 매니 워커즈 에잇 헬씨어 런치즈", keys: [ { en: "cafeteria", ko: "구내식당" }, { en: "healthier lunches", ko: "더 건강한 점심" } ] },
  { id: "p5-278", topic: "건강", function: "연결", en: "As a result, employees felt less tired in the afternoon and worked more productively.", ko: "그 결과 직원들은 오후에 피로를 덜 느꼈고 더 생산적으로 일했다.", pron: "애저 리절트 엠플로이이즈 펠트 레스 타이어드 인 디 애프터눈 앤 웍트 모어 프러덕티블리", keys: [ { en: "less tired", ko: "덜 피곤한" }, { en: "more productively", ko: "더 생산적으로" } ] },
  { id: "p5-279", topic: "건강", function: "결론", en: "Therefore, supporting employees' wellness brings lasting benefits to the whole company.", ko: "따라서 직원들의 건강과 복지를 지원하는 것은 회사 전체에 지속적인 이점을 가져다준다.", pron: "데어포어 서포팅 엠플로이이즈 웰니스 브링즈 래스팅 베니핏츠 투 더 호울 컴퍼니", keys: [ { en: "employees' wellness", ko: "직원들의 건강(웰니스)" }, { en: "lasting benefits", ko: "지속적인 이점" } ] },
  { id: "p5-280", topic: "대중교통", function: "의견 시작", en: "I strongly believe that cities should expand subway lines and electric buses.", ko: "나는 도시가 지하철 노선과 전기 버스를 확충해야 한다고 강력히 믿는다.", pron: "아이 스트롱리 빌리브 댓 시티즈 슈드 익스팬드 섭웨이 라인즈 앤 일렉트릭 버시즈", keys: [ { en: "expand subway lines", ko: "지하철 노선을 확충하다" }, { en: "electric buses", ko: "전기 버스" } ] },
  { id: "p5-281", topic: "대중교통", function: "이유", en: "First of all, a convenient transit system encourages people to leave their cars at home.", ko: "무엇보다도 편리한 대중교통 체계는 사람들이 자가용을 집에 두고 나오도록 유도한다.", pron: "퍼스트 오브 올 어 컨비니언트 트랜짓 시스템 인커리지즈 피플 투 리브 데어 카즈 앳 홈", keys: [ { en: "transit system", ko: "대중교통 체계" }, { en: "leave their cars at home", ko: "차를 집에 두고 오다" } ] },
  { id: "p5-282", topic: "대중교통", function: "예시", en: "For instance, when a new subway line opened in my district, my commuting time dropped by half.", ko: "예를 들어 우리 지역에 새 지하철 노선이 개통되었을 때 내 통근 시간이 절반으로 줄었다.", pron: "포 인스턴스 웬 어 뉴 섭웨이 라인 오픈드 인 마이 디스트릭트 마이 커뮤팅 타임 드랍트 바이 해프", keys: [ { en: "new subway line", ko: "새 지하철 노선" }, { en: "dropped by half", ko: "절반으로 줄었다" } ] },
  { id: "p5-283", topic: "대중교통", function: "연결", en: "As a result, the traffic congestion on the main roads decreased noticeably during rush hour.", ko: "그 결과 출퇴근 시간대에 주요 도로의 교통 체증이 눈에 띄게 줄어들었다.", pron: "애저 리절트 더 트래픽 컨제스천 온 더 메인 로우즈 디크리스트 노티서블리 듀링 러쉬 아워", keys: [ { en: "traffic congestion", ko: "교통 체증" }, { en: "rush hour", ko: "출퇴근 시간대" } ] },
  { id: "p5-284", topic: "대중교통", function: "결론", en: "Therefore, I think improving public transportation makes a city cleaner and more livable.", ko: "따라서 나는 대중교통을 개선하는 것이 도시를 더 깨끗하고 살기 좋게 만든다고 생각한다.", pron: "데어포어 아이 띵크 임프루빙 퍼블릭 트랜스포테이션 메익스 어 시티 클리너 앤 모어 리버블", keys: [ { en: "improving public transportation", ko: "대중교통을 개선하는 것" }, { en: "more livable", ko: "더 살기 좋은" } ] },
  { id: "p5-285", topic: "의견 시작", function: "의견 시작", en: "From my perspective, learning from mistakes is the fastest way to improve at work.", ko: "내 관점에서는 실수로부터 배우는 것이 직장에서 실력을 키우는 가장 빠른 방법이다.", pron: "프럼 마이 퍼스펙티브 러닝 프럼 미스테익스 이즈 더 패스티스트 웨이 투 임프루브 앳 웍", keys: [ { en: "From my perspective,", ko: "내 관점에서는" }, { en: "learning from mistakes", ko: "실수로부터 배우는 것" } ] },
  { id: "p5-286", topic: "이유", function: "이유", en: "Thanks to regular feedback, employees can fix small problems early and grow faster.", ko: "정기적인 피드백 덕분에 직원들은 작은 문제를 일찍 고치고 더 빨리 성장할 수 있다.", pron: "쌩스 투 레귤러 피드백 엠플로이이즈 캔 픽스 스몰 프라블럼즈 얼리 앤 그로우 패스터", keys: [ { en: "regular feedback", ko: "정기적인 피드백" }, { en: "fix small problems", ko: "작은 문제를 고치다" } ] },
  { id: "p5-287", topic: "예시", function: "예시", en: "When I made a small mistake on my first report, my team leader kindly showed me how to fix it.", ko: "내가 첫 보고서에서 작은 실수를 했을 때 팀장님이 고치는 법을 친절하게 알려 주셨다.", pron: "웬 아이 메이드 어 스몰 미스테익 온 마이 퍼스트 리포트 마이 팀 리더 카인들리 쇼우드 미 하우 투 픽스 잇", keys: [ { en: "team leader", ko: "팀장" }, { en: "showed me how to fix it", ko: "고치는 방법을 보여 주었다" } ] },
  { id: "p5-288", topic: "연결", function: "연결", en: "Even though it was embarrassing at that time, I learned an important lesson and never repeated it.", ko: "비록 그때는 부끄러웠지만 나는 중요한 교훈을 배웠고 다시는 같은 실수를 반복하지 않았다.", pron: "이븐 도우 잇 워즈 임배러싱 앳 댓 타임 아이 런드 언 임포턴트 레슨 앤 네버 리피티드 잇", keys: [ { en: "at that time", ko: "그때, 당시에" }, { en: "learned an important lesson", ko: "중요한 교훈을 배웠다" } ] },
  { id: "p5-289", topic: "결론", function: "결론", en: "This is why I believe a supportive culture helps everyone perform at their best.", ko: "이것이 바로 서로 돕는 문화가 모두가 최고의 역량을 발휘하도록 돕는다고 내가 믿는 이유이다.", pron: "디스 이즈 와이 아이 빌리브 어 서포티브 컬쳐 헬프스 에브리원 퍼폼 앳 데어 베스트", keys: [ { en: "This is why I believe", ko: "이것이 내가 ~라고 믿는 이유이다" }, { en: "perform at their best", ko: "최고의 역량을 발휘하다" } ] },
  { id: "p5-290", topic: "결론", function: "결론", en: "All things considered, I am convinced that this approach brings the greatest long-term benefits.", ko: "모든 것을 고려해 볼 때 나는 이 방식이 장기적으로 가장 큰 이점을 가져온다고 확신한다.", pron: "올 띵즈 컨시더드 아이 앰 컨빈스트 댓 디스 어프로치 브링즈 더 그레이티스트 롱텀 베니핏츠", keys: [ { en: "All things considered,", ko: "모든 것을 고려해 볼 때" }, { en: "long-term benefits", ko: "장기적인 이점" } ] }
];
